window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_017"]={"n":"董元恺","dyn":"清","poems":[{"t":"闲中好 其一 别意","f":"古风","c":["闲中好。","别意生庭草。","含泪向窗纱。","残痕照落花。"]},{"t":"闲中好 其二 别意","f":"古风","c":["闲中好。","春信吹芳草。","裙带绿于烟。","东风又几年。"]},{"t":"明月斜 夜坐","f":"古风","c":["篆烟红，泪花绿。","银汉迢迢堕入怀，黄河万里响心曲。"]},{"t":"南歌子 其一 闺怨","f":"古风","c":["侬取冰为枕，侬持檗作衾。","一夜苦寒侵。","五更天欲曙，涕淫淫。"]},{"t":"南歌子 其二 闺怨","f":"古风","c":["郎似江边水，侬如江上花。","花落水无涯。","东风吹欲起，逐风斜。"]},{"t":"三台令 其一 洞庭杂兴","f":"古风","c":["万顷平湖似镜，千峰列嶂如环。","处处倪迂范缓，家家雾髻云鬟。"]},{"t":"三台令 其二 洞庭杂兴","f":"古风","c":["策杖丹梯翠巘，肩舆绿意红情。","籍草争来献茗，提壶忽地听莺。"]},{"t":"三台令 其三 洞庭杂兴","f":"古风","c":["幽是包山林屋，高为飘渺仙峰。","揽胜石公石姆，探奇大龙小龙。"]},{"t":"三台令 其四 洞庭杂兴","f":"古风","c":["锦泛千层桃浪，光摇万树梨花。","树树红飞白雪，层层碧映朱霞。"]},{"t":"三台令 其五 洞庭杂兴","f":"古风","c":["销夏山林城市，中春剖橘搓橙。","一叶舟浮个个，前帆阁带盈盈。"]},{"t":"三台令 其六 洞庭杂兴","f":"古风","c":["宅有鸱彝少伯，巷传角里先生。","山果赧颜可摘，湖鱼缩项旋烹。"]},{"t":"三台令 其七 洞庭杂兴","f":"古风","c":["日落山空响梵，风来树杪生涛。","一卷洞中周易，三杯醉后离骚。"]},{"t":"摘得新 其一 闺思","f":"古风","c":["烛灭时。","思郎泪暗垂。","相思谁与共，月明知。","月明照出相思字，是郎诗。"]},{"t":"摘得新 其二 咏玉簪花","f":"古风","c":["白玉簪，瑶池月影临。","搔头斜照水，鬓云侵。","阿谁不放愁心展，正多心。"]},{"t":"花非花 其一 古意","f":"古风","c":["黄檗篱，合欢树。","树成蹊，篱当户。","侬身不共合欢时，侬心偏见生离苦。"]},{"t":"花非花 其二 古意","f":"古风","c":["柳缄愁，蕉结恨。","恨千条，愁一寸。","郎行终日无舒时，郎来一夜都开尽。"]},{"t":"花非花 其三 咏韭","f":"古风","c":["舍东畦，霜后圃。","比青篘，舒翠缕。","知君昨夜故人来，为我殷勤剪春雨。"]},{"t":"南歌子 其一 闺绣","f":"古风","c":["螺笔描新样，金针倚绣床。","深情却悔绣鸳鸯。","绣出无情蛱蝶，又成双。"]},{"t":"南歌子 其二 别况","f":"古风","c":["泪落吹成絮，愁多乱似丝。","偎人刚道莫相思。","却是相思此夜，起头时。"]},{"t":"南歌子 其三 闺夜","f":"古风","c":["绛蜡啼千箸，冰蚕搅万丝。","空房香烬欲消时。","冷暖争如宝鸭，腹中知。"]},{"t":"荷叶杯 闺夜","f":"古风","c":["捲起一帘清景。","孤影。","小胆怯空庭。","乱竹萧萧响画屏。","听么听。","听么听。"]},{"t":"望江南 啜茶十咏 其一","f":"古风","c":["茶坞胜，阳羡郁层峦。","月峡涧流生雀舌，石岩雾晓出龙团。","仙掌片峰寒。"]},{"t":"望江南 啜茶十咏 其二","f":"古风","c":["茶笋别，罗岕胜乌程。","庙后结花垂绿脚，渚前分露种红英。","秀色带烟轻。"]},{"t":"望江南 啜茶十咏 其三","f":"古风","c":["茶籯满，叶叶占先春。","翠霭撷齐双鬓冷，青丝笼就两枪新。","衣惹暗香尘。"]},{"t":"望江南 啜茶十咏 其四","f":"古风","c":["茶舍小，石径卧云斜。","斑驳苔生青嶂影，婆娑树老绿阴遮。","竹里看煎茶。"]},{"t":"望江南 啜茶十咏 其五","f":"古风","c":["茶灶冷，溪鸟逐烟光。","瑟瑟波沉霞脚碎，轻轻色泛乳花香。","翠釜合先尝。"]},{"t":"望江南 啜茶十咏 其六","f":"古风","c":["茶焙暖，沆瀣碧波融。","编竹候随文武火，开缄叶里建城笼。","一纸隔春风。"]},{"t":"望江南 啜茶十咏 其七","f":"古风","c":["茶泉沸，第二擅中泠。","旋沫翻成鱼眼动，腾波声作老龙听。","涧底觅樵青。"]},{"t":"望江南 啜茶十咏 其八","f":"古风","c":["茶瓯洁，碧碗醉春醪。","翠影香浮卢氏碗，素瓷圆胜谢家窑。","丝柳拂长条。"]},{"t":"望江南 啜茶十咏 其九","f":"古风","c":["茶品绝，缀玉复含珠。","三十绫文酬博士，两篇《茶录》问君谟。","疏月下庭梧。"]},{"t":"望江南 啜茶十咏 其十","f":"古风","c":["茶候静，帘卷日初长。","片甲味分蝉翼薄，丹丘阴益簟纹凉。","应唤醒羲皇。"]},{"t":"望江南 其十一 红桥春游词","f":"古风","c":["红桥好，联骑出城闉。","映日游丝萦曲径，扑天飞絮惹香尘。","胜地占芳辰。"]},{"t":"望江南 其十二 红桥春游词","f":"古风","c":["虹桥好，挈伴踏青游。","紫陌骄嘶金勒马，碧波斜蘸绿杨楼。","高会尽风流。"]},{"t":"望江南 其十三 红桥春游词","f":"古风","c":["虹桥好，潋滟画栏明。","曲折湘文摇簟縠，玲珑梵字漾帘旌。","高下渌波平。"]},{"t":"望江南 其十四 红桥春游词","f":"古风","c":["虹桥好，万树带垂杨。","新笋穿泥云覆屋，疏篱列障竹为墙。","魂断旧雷塘。"]},{"t":"望江南 其十五 红桥春游词","f":"古风","c":["虹桥好，摇曳酒旗红。","小立垂丝人语细，低回促坐笑声浓。","莫放绿樽空。"]},{"t":"望江南 其十六 红桥春游词","f":"古风","c":["红桥好，野店擅行厨。","细切银丝盐下豉，新调玉鲙笋如酥。","餔醊足欢呼。"]},{"t":"望江南 其十七 红桥春游词","f":"古风","c":["虹桥好，画舫树中移。","万缕轻黄珠户映，半篙柔绿绣帘垂。","春昼日迟迟。"]},{"t":"望江南 其十八 红桥春游词","f":"古风","c":["虹桥好，听曲和鸾箫。","舞榭丝牵傀儡动，兰舟风送管弦遥。","翠袖暗相招。"]},{"t":"望江南 其十九 红桥春游词","f":"古风","c":["虹桥好，绕径印苍苔。","纨扇慢摇遮鬓影，玉纤小摘落青梅。","伫立共徘徊。"]},{"t":"望江南 其二十 红桥春游词","f":"古风","c":["虹桥好，懊恼是言归。","好鸟啼春相唤住，浓花对酒欲争飞。","客思正依依。"]},{"t":"望江南 其二十一 青墩初夏词","f":"古风","c":["青墩好，别业号苍梧。","万树浓荫含雾雨，满园空翠映菰蒲。","一幅辋川图。"]},{"t":"望江南 其二十二 青墩初夏词","f":"古风","c":["青墩好，四面一溪遥。","丝缕风垂青捲幔，玻瓈水涨绿平桥。","楼阁晕春潮。"]},{"t":"望江南 其二十三 青墩初夏词","f":"古风","c":["青墩好，一苇放中流。","星渚频移天上坐，岸花飞送镜中游。","诗酒任沉浮。"]},{"t":"望江南 其二十四 青墩初夏词","f":"古风","c":["青墩好，乐事胜花朝。","旁舍煆泥载茉莉，小鬟敲竹护樱桃。","长日尽逍遥。"]},{"t":"望江南 其二十五 青墩初夏词","f":"古风","c":["青墩好，曲院扇和风。","玫瑰斜簪云鬓紫，蔷薇高架锦屏红。","裁剪夺天工。"]},{"t":"望江南 其二十六 青墩初夏词","f":"古风","c":["青墩好，绝胜浣花溪。","绕砌翅翻蝴蝶舞，映山血染杜鹃啼。","烟景忽凄迷。"]},{"t":"望江南 其二十七 青墩初夏词","f":"古风","c":["青墩好，趺坐荫休篁。","种擅乌椑收柿叶，丝牵青蔓种菱塘。","拂袖满幽香。"]},{"t":"望江南 其二十八 青墩初夏词","f":"古风","c":["青墩好，杖履入平芜。","旧雨一枝鸠唤妇，新巢千尺鹤将雏。","相劝倒琼苏。"]},{"t":"望江南 其二十九 青墩初夏词","f":"古风","c":["青墩好，对景且衔杯。","粉节新涂抽紫箨，红盐初下摘青梅。","怀抱一时开。"]},{"t":"望江南 其三十 青墩初夏词","f":"古风","c":["青墩好，荇藻积空明。","跃入锦鳞堪上箸，网来文雉足调羹。","肠断一声莺。"]},{"t":"潇湘神 其一 四女祠","f":"古风","c":["四女祠。","四女祠。","白发红颜未嫁时。","但使宁亲成孝子，不愁天下少男儿。"]},{"t":"潇湘神 其二 四女祠","f":"古风","c":["杨柳枝。","杨柳枝。","碧瓦飘风散雨丝。","一树棠梨春社后，千年留得几行诗。"]},{"t":"捣练子 其一 和内寄原韵","f":"古风","c":["愁脉脉，水盈盈。","握手临歧无限情。","揾着啼痕双袖泪，笑从花里送郎行。"]},{"t":"捣练子 其二 和内寄原韵","f":"古风","c":["江树隔，岭云开。","历尽东风未遣回。","惆怅五更孤枕上，与卿刚在梦中来。"]},{"t":"捣练子 其三 和内寄原韵","f":"古风","c":["消永夜，剔残缸。","暖语分明向绮窗。","留得别时千点泪，罗衣犹未浣春江。"]},{"t":"字字双 欢情","f":"七言绝句","c":["一枝容膝安复安。","金风玉露寒复寒。","连呼侬字欢复欢。","欢情如月看复看。"]},{"t":"忆王孙 其一 江上","f":"古风","c":["一江江水阅兴亡。","花月春江事渺茫。","江上风吹雁两行。","泪沾裳。","江北江南总断肠。"]},{"t":"忆王孙 其二 小鬟捧茶","f":"古风","c":["二泉初汲碾旗枪。","火沸松声路沁香。","郑重双鬟手自将。","敢先尝。","春风滋味怯萧郎。"]},{"t":"一叶落 秋忆","f":"古风","c":["一叶落。","伤漂泊。","寸心万里阑干角。","天边望断鸿，枝头问灵鹊。","问灵鹊。","几度浑如昨。"]},{"t":"转应曲 其一 送别","f":"古风","c":["相送。","相送。","门外远钟残梦。","千山万水郎程。","一夜五更月明。","明月。","明月。","偏是照人离别。"]},{"t":"转应曲 其二 春闺","f":"古风","c":["双燕。","双燕。","春色衔来一片。","爱伊画阁多情。","打散枝头晓莺。","莺晓。","莺晓。","又听子规啼早。"]},{"t":"如梦令 其一 梦后","f":"古风","c":["枝上啼鹃如诉。","唤起离愁无数。","曲径古云深，隔岸梦中来路。","回顾。","回顾。","月约花阴西度。"]},{"t":"如梦令 其二 闺情，和李易安韵","f":"古风","c":["忽地披衣起坐。","梦也分明真个。","梦后更凄凉，生怕梦来难躲。","无那。","无那。","守着影儿伴我。"]},{"t":"如梦令 其三 闺别，和王修微韵","f":"古风","c":["半枕别时残梦。","一纸离愁新咏。","昨夜月明中，几处小桥霜冻。","相送。","相送。","泪湿轻衫寒重。"]},{"t":"归自谣 归梦","f":"古风","c":["东风急。","携手罗帏情脉脉。","分明悄语莺花夕。","梦回依旧关山隔。","空相忆。","春云遮断春归迹。"]},{"t":"望江怨 闺怨","f":"古风","c":["春云晚。","妾泪朝朝长在眼。","影动湘裙展。","平湖绿水明如剪。","难消遣。","一夜正愁深，东风忽吹浅。"]},{"t":"定西番 春暮，集唐词","f":"古风","c":["隐映画屏开处，莺对语，蝶飞狂。","惜韶光。","罗袂从风轻举，波影满池塘。","高捲水晶帘额，衬斜阳。"]},{"t":"长相思 其一 闺忆","f":"古风","c":["梅花风。","楝花风。","二十四番花信风。","花开花落中。","吴江东。","楚江东。","潮落春江东复东。","春魂一点通。"]},{"t":"长相思 其二 闺忆","f":"古风","c":["晓云峰。","暮云峰。","郎处云深第几峰。","愁来簇两峰。","水连空。","月横空。","刚得相逢总是空。","相逢怕梦中。"]},{"t":"相见欢 鸳鸯","f":"古风","c":["珍禽两两回翔。","狎芳塘。","惹得多情儿女，绣罗裳。","嗔伊并，惊伊散，忽分行。","刚到荷花深处，又双双。"]},{"t":"望梅花 岭南至日，梅花盛开","f":"古风","c":["何事粤东无雪。","万树垂垂先白。","一线初添疏影夕。","零乱冷烟残月。","瘐岭经年驿使隔。","谁寄江南消息。"]},{"t":"醉太平 其一 旧游","f":"古风","c":["红楼卧游。","青楼梦游。","旧游重倚楼头。","捲东风上钩。","春山欲浮。","秋波欲流。","妆成春影横秋。","对花枝坐愁。"]},{"t":"醉太平 其二 花间","f":"古风","c":["花奴雁奴。","花姑鼠姑。","花间鸟唤提壶。","倩花间酒沽。","龙刍鹿庐。","麟符象弧。","酣来斫地歌呼。","识人间故吾。"]},{"t":"醉太平 其三 钱歌","f":"古风","c":["榆钱绿钱。","苔钱碧钱。","圆如锦石青钱。","弄芙蕖小钱。","流钱雨钱。","连钱影钱。","小斋夜落金钱。","值东风几钱。"]},{"t":"醉太平 其四 钱歌","f":"古风","c":["郑钱沈钱。","缗钱侧钱。","诗书争似囊钱。","看空囊一钱。","床头百钱。","杖头百钱。","张公万选青钱。","选刘公大钱。"]},{"t":"薄命女 其一 有约","f":"古风","c":["花阴悄。","罗袜潜移芳径小。","惊起枝头鸟。","几遍画栏闲倚，无数心烟空袅。","只恐星光天欲晓。","旋把灯吹了。"]},{"t":"薄命女 其二 夜听捣衣声","f":"古风","c":["声凄切。","一派清砧愁欲绝。","万户秋光滴。","远如繁筝响急，近似寒蛩低咽。","梦断玉关无信息。","思妇心偏结。"]},{"t":"生查子 其一 闺怨","f":"五言律诗","c":["送郎上车轮，车远郎亦远。","愿作车后尘，处处随郎转。","郎行辙不归，妾泪不离眼。","看取眼泪痕，与辙谁深浅。"]},{"t":"生查子 其二 闺情，集唐诗","f":"五言律诗","c":["欲试一寸心，试妾与君泪。","寄向故园流，空望去时水。","不消出门行，想君发扬子。","错认几人船，日暮情何已。"]},{"t":"生查子 其三 闺情，集唐诗","f":"五言律诗","c":["应为别离多，愁眠罗帐晓。","是妾断肠时，谁知妾怀抱。","娇郎痴若云，夜夜梦中到。","春意罢帘栊，暗飞萤自照。"]},{"t":"生查子 其四 闺情，集唐诗","f":"五言律诗","c":["悲妾似花身，能得几时好。","空将泪见花，花落知多少。","不复理残机，织锦心草草。","频放剪刀声，双眉灯下扫。"]},{"t":"醉公子 其一 闺情，集唐诗","f":"五言律诗","c":["独坐裁新锦。","天寒剪刀冷。","方觉泪难裁。","丹心一寸灰。","晓卧半床月。","月落子规歇。","归在落花前。","春风正可怜。"]},{"t":"醉公子 其二 闺情，集唐诗","f":"五言律诗","c":["破得东风恨。","畏人相借问。","还恐是愁中。","银床一半空。","倘随明月去。","月满门前路。","犹有万重思。","归心梦独知。"]},{"t":"醉公子 其三 闺情，集唐诗","f":"五言律诗","c":["落花相与恨。","即是春风尽。","不敢怨春风。","细看枝上红。","遥将一点泪。","两处滴池水。","池水晓来深。","长悬零落心。"]},{"t":"醉公子 其四 闺情，集唐诗","f":"五言律诗","c":["袅袅城边柳。","骀荡郎知否。","争取最长条。","相思一水遥。","相思杳如梦。","莫引西风动。","剪蜡泪争流。","残灯照卧幽。"]},{"t":"春光好 过沉香亭址","f":"古风","c":["荒亭北，夕阳空。","晚烟笼。","倾国名花何处，只春风。","自是羽衣尘土，采蘋休怨楼东。","一样梨花寒食夜，翠微中。"]},{"t":"蝴蝶儿 本意，和唐人张泌韵","f":"古风","c":["蝴蝶儿。","绣窗时。","怪他轻薄上郎衣。","停针试觑伊。","且把罗巾扑，休教捉对飞。","褪残香粉画胭脂。","依然双翅垂。"]},{"t":"昭君怨 昭君塞外命重制琵琶，曰浑不似","f":"古风","c":["莫谓汉宫人巧。","便有琵琶难肖。","毳帐草萧萧。","梦魂遥。","薄命玉容如此。","值得一声情死。","边月下祈连。","影堪怜。"]},{"t":"太平时 闺怨","f":"古风","c":["宝瑟凄凉怨岁华。","倚窗纱。","个侬生性似杨花。","逐风斜。","忽听一声啼杜宇，自嗟呀。","年年啼罢不还家。","只天涯。"]},{"t":"抛球乐 美人蹴鞠","f":"古风","c":["香阁妆成约伴来。","斜穿鞠域映楼台。","红巾吹向红帮乱，波影轻摇鬓影开。","猛被檀奴觑，潜匿花阴去不回。"]},{"t":"女冠子 其一 登穹窿山，赠施鍊师","f":"古风","c":["穹窿飘渺。","碧海三山瑶草。","剑光寒。","玉斧滋晴露，琼花护醮坛。","灵随龙竹引，香逐凤箫残。","隐现金天掌，是毫端。"]},{"t":"女冠子 其二 闺人礼佛","f":"古风","c":["宝莲幢畔。","清晓纤纤频盥。","到香台。","唵叭随烟结，菩提带树开。","粉痕侵贝叶，心字印炉灰。","更把鹦哥教，念如来。"]},{"t":"醉花间 其一 即事，拟毛文锡体","f":"古风","c":["休相近。","还相近。","相近低声问。","昨夜梦中人，暗送横波认。","情多不讳痴，爱极翻成恨。","来朝怕别离，又把啼痕揾。"]},{"t":"醉花间 其二 密怨","f":"古风","c":["莫相怨。","频相见。","相见何曾怨。","一见一回眸，羞眤旁人面。","波澜任枕衾，猜妒真欢恋。","懊恼是春风，郎处春风便。"]},{"t":"点绛唇 其一 春归","f":"古风","c":["杜宇年年，声声只唤春归去。","春归何处。","且把帘垂住。","帘捲东风，春竟穿帘去。","留难住。","放春归去。","来岁春来处。"]},{"t":"点绛唇 其二 闺人语燕，和李清照韵","f":"古风","c":["燕子双双，阿谁系得红丝缕。","妆台衔去。","落尽香泥雨。","好向郎边，细语相思绪。","归来处。","潇湘烟水，珍重江南路。"]},{"t":"湿罗衣 雨中度茗岭","f":"古风","c":["盘盘石磴插天高。","茫茫嶂海波涛。","雾合芒鞋，云生缊袍。","奔流飞涧千条。","响层霄。","光摇绿筱，香清紫笋，翠影迢遥。"]},{"t":"浣溪沙 其一 春闺","f":"七言古诗","c":["莺语听残春院晴。","屏云倚其晚寒凝。","黛痕愁入远峰青。","庭满落花香寂寂，声和玉漏夜清清。","轻红拂萝晓来醒。"]},{"t":"浣溪沙 其二 回前调","f":"七言古诗","c":["醒来晓梦拂红轻。","清清夜漏玉和声。","寂寂香花落满庭。","青峰远入愁痕黛，凝寒晚共倚云屏。","晴院春残听语莺。"]},{"t":"浣溪沙 其三 春闺，集唐词","f":"七言古诗","c":["绮陌春深翠袖香。","水纹簟冷画屏凉。","月窗花径梦悠飏。","将见客时微掩敛，几回拼却又思量。","此情谁会倚斜阳。"]},{"t":"菩萨蛮 闺情，集唐诗","f":"古风","c":["闲倚绣帘吹柳絮。","已成残梦随君去。","明月为谁圆。","情教细语传。","春风别有意。","凭添两行泪。","怅望此何时。","只应君自知。"]},{"t":"卜算子 秋闺，集唐诗","f":"古风","c":["花点石榴裙，虫响灯光薄。","心怯空房不忍归，风动秋千索。","望月想蛾眉，菊露凄罗幕。","几度金刀试剪裁，红泪双双落。"]},{"t":"减字木兰花 其一 浴温泉","f":"古风","c":["九龙汤沸。","范阳水设鱼龙戏。","洗罢奚儿。","翻作奚儿洗马池。","仓皇西幸。","马嵬坡下长生竟。","河水汤汤。","南内无人有寿王。"]},{"t":"减字木兰花 其二 浴温泉","f":"古风","c":["夜深清影。","芳草不生泉欲冷。","绣岭花开。","尽逐东流去不回。","梨园按曲。","羯鼓声中鼙鼓蹙。","红粉成灰。","村笛还吹阿滥堆。"]},{"t":"巫山一段云 悼友","f":"古风","c":["雨洒空床笛，风号败壁琴。","泉台一别信沉沉。","肠断到而今。","把酒魂应绝，题诗涕不禁。","孤灯悄向梦中寻。","路隔小窗阴。"]},{"t":"诉衷情 金陵春望","f":"古风","c":["孝陵衰草下牛羊。","春风绕建康。","一片降帆过眼，短笛倚斜阳。","君莫问，石头冈。","寝园荒。","铁锁沉沉，金凫寂寂，玉树茫茫。"]},{"t":"丑奴儿令 其一 别情","f":"古风","c":["匆匆帘影惊分处，蓦别萧郎。","自别萧郎。","风雨忧愁一半妨。","从今谙禁愁滋味，总不思量。","却又思量。","日日车轮更转肠。"]},{"t":"丑奴儿令 其二 美人对镜","f":"古风","c":["我似个人伊似我，伊自知愁。","我更多愁。","两颊啼痕一处留。","春来总与伊同瘦，伊在眉头。","我在心头。","一点横波两处流。"]},{"t":"谒金门 湖舫同内泛雨","f":"古风","c":["烟舫织。","荡破满湖轻碧。","一片楼台空翠滴。","两峰连树失。","帘外荷香堪裛。","槛底鱼游争识。","钗漾菱花鬟影湿。","镜里随风入。"]},{"t":"好事近 薰笼","f":"古风","c":["数缕气氤氲，微透玲珑湘竹。","小玉频添鹊脑，比衔花箫局。","半薰绣幔半笼裙，尽放馀烟续。","一任帘前被底，长共香奁宿。"]},{"t":"柳含烟 至日韶阳见柳","f":"古风","c":["韶阳柳，季冬时。","摇曳青青如许，添来宫线织成丝。","舞腰肢。","寒塘绿映春波晓。","镇日黛眉颦笑。","不吹风雪却吹烟。","曲江边。"]},{"t":"好时光 杨妃山茶","f":"古风","c":["一捻指痕轻染，千片汗色微销。","乍醒沉香亭上梦，芳魂带叶飘。","照耀临池处，恍上马映多娇。","疑向三郎语，时作舞纤腰。"]},{"t":"一落索 咏风鸢","f":"古风","c":["鸷鸟凭空而起。","云霄堪致。","青春一线上青天，禁得无声堕地。","怪底轻狂可喜。","欲飞还止。","十年前事忆儿童，此日依然故纸。"]},{"t":"忆秦娥 其一 湖楼和内","f":"古风","c":["妆楼悄。","锦塘风送闻啼鸟。","闻啼鸟。","湖光如梦，乱云缭绕。","六桥裙带飘芳草。","两峰高画春山小。","春山小。","珠帘初捲，画船多少。"]},{"t":"忆秦娥 其二 不归","f":"古风","c":["伤心极。","年年惯作天涯客。","天涯客。","留他不住，送他不得。","不如归去啼声咽。","不归休记归时节。","归时节。","未容言语，又成离别。"]},{"t":"更漏子 其一 寄忆","f":"古风","c":["旧愁人，新愁月。","同是黄昏时节。","人不见，月偏明。","除非倩梦寻。","寒衾拥。","愁难送。","不到四更无梦。","莲漏滴，乳鸦啼。","梦儿能几时。"]},{"t":"更漏子 其二 闺情，集唐词","f":"古风","c":["雨初晴，帘半捲。","叠损罗衣金线。","绡幌碧，粉屏空。","灯花结碎红。","思无穷，情未了。","一炷后庭香袅。","春如剪，雨如丝。","风摇夜合枝。"]},{"t":"更漏子 其三 闺情，集唐词","f":"古风","c":["绣帘垂，幽沼渌。","倚遍阑干几曲。","蘋叶软，草烟低。","绿窗残梦迷。","玉纤轻，凤箫歇。","梦觉半床残月。","兰烛灺，柳条空。","此情千万重。"]},{"t":"更漏子 其四 闺情，集唐词","f":"古风","c":["晚妆残，春态浅。","远岫参差迷眼。","千万恨，在心头。","秋波横欲流。","燕双双，人悄悄。","残月光沉树杪。","烟雾冷，画屏幽。","吴山点点愁。"]},{"t":"清平乐 端午闺中词 其一 健人","f":"古风","c":["缕丝裁绢。","小小人名健。","但得一心常缱绻。","两好时时对面。","临风故作娉婷。","看花想像仪形。","任取钗横鬓乱，年年祝向芳龄。"]},{"t":"清平乐 其二 茧虎","f":"古风","c":["冰蚕细茧。","纤手亲裁剪。","刻画爪牙眉与眼。","一笑从风细转。","有时綵笔描真。","何须插艾为人。","飘向玉钗头上，儿童竞取相亲。"]},{"t":"清平乐 其三 长命缕","f":"古风","c":["谁能续命。","五色交相映。","浪说辟兵还压胜。","茧馆珠囊堪赠。","不须绕户高悬。","料应妆臂同缠。","愿取一丝一岁，与郎情绪绵绵。"]},{"t":"清平乐 其四 辟兵符","f":"古风","c":["心前笑抚。","神印穿金缕。","销得五兵刚二五。","好共钗头艾虎。","依依插鬓宜春。","翩翩佩带宜人。","全仗赤符厮守，不教胆怯空庭。"]},{"t":"清平乐 其五 绫包角黍","f":"古风","c":["萦丝楚粽。","巧借针神缝。","杂俎轻镂花影动。","却比菰蒲郑重。","陋他九子殊名。","随他百索殊形。","好是餐他秀色，鬓边袅袅婷婷。"]},{"t":"清平乐 其六 菖蒲葫芦","f":"古风","c":["花阴午直。","旋把菖蒲刻。","依样雕锼纤指劈。","细认灵根九节。","五丝撷向霓裳。","一樽醉泛瑶觞。","共喜兰汤浴罢，携来倍觉芬芳。"]},{"t":"误佳期 湖楼月夜，和龚芝麓先生韵","f":"古风","c":["月色初穿帘幕。","掩映玉人绰约。","满身花影倩扶持，几处清砧作。","香销玉臂寒，雾冷金钗落。","醉擘银筝信手弹，一曲秋云薄。"]},{"t":"相思引 烧香曲","f":"古风","c":["暖语红窗体自芬，笑添沉水更氤氲。","语香花气，常共夜深闻。","一缕轻烟遮不住，剪来银叶衬还薰。","炙成心字，双守鹊炉温。"]},{"t":"忆少年 春闺","f":"古风","c":["春尘如雨，春风如醉，春光如梦。","春花独对也，只春波微动。","剪破春阴春色好，更春情落红催送。","萋萋春草碧，恰补春愁空。"]},{"t":"荆州亭 登望湖亭","f":"古风","c":["咫尺烟云万状。","摇曳帆樯百丈。","放眼是江南，隔断一湖波浪。","碧浸芙蓉春涨。","白映楚天空漾。","愿借马当风，安稳行人无恙。"]},{"t":"眉峰碧 画眉","f":"古风","c":["早展菱花待。","昨试轻螺在。","盈盈斜印两春山，恰与秋波厮对。","深浅还应配。","浓淡都堪爱。","不知何处送愁来，蛾弯两笔愁难载。"]},{"t":"阮郎归 窗前","f":"古风","c":["簸钱年纪只些些。","垂鬟鬓未鸦。","别来几度海桐花。","窗前细认他。","奁镜畔，绣帘遮。","妆成覆额纱。","一枝春色落谁家。","眉边散晓霞。"]},{"t":"画堂春 其一 蝴蝶花","f":"古风","c":["春烟春雨染浓芳。","丝丝绣出春光。","映阶碧草学轻狂。","舞遍东墙。","栩栩欲迷庄子，翩翩胜拓滕王。","穿花潜入此花藏。","细认钗梁。"]},{"t":"画堂春 其二 十姊妹","f":"古风","c":["天然一色绮罗丛。","妆成并倚东风。","秦姨总与虢姨同。","玉质烟笼。","馥馥幽香密蕊，姗姗淡白轻红。","相携竞入翠薇宫。","不妒芳容。"]},{"t":"画堂春 其三 荷花蔷薇","f":"古风","c":["东风无力锦屏遮。","依稀露软烟斜。","繁华满径拂窗纱。","翠剪明霞。","高处牵衣欲语，低边弄影交加。","一帘月色浸荷花。","绿水人家。"]},{"t":"玉连环 夜落金钱","f":"古风","c":["银屏碧锁空云叆。","金绯绚彩。","豫州赌胜掷红幺，试比青蚨几倍。","纤手折来相对。","五铢堪爱。","秋光也自到贫家，一线斜阳难卖。"]},{"t":"海棠春 闺词，和王阮亭先生韵 其一 晓妆","f":"古风","c":["枕棱斜溜金钗响。","人倦起、日高朱网。","揽镜怯梳头，一点情波漾。","牡丹新髻翻时样。","怪陌上、游郎争赏。","鬌试残妆，日暖云鬟敞。"]},{"t":"海棠春 其二 午睡","f":"古风","c":["海棠花下春风足。","停针线、忽萦心曲。","晓梦未分明，还向鸳鸯褥。","簟纹碧映红生肉。","瞤睡眼、醉花柔玉。","惊认是朝晖，影落湘妃竹。"]},{"t":"海棠春 其三 晚浴","f":"古风","c":["玉盘水浸金钿影。","清波映、红潮微醒。","娇艳体生香，露湿梨花冷。","起来唤婢移奁镜。","忙掩敛、罗裙先整。","风袅水沉烟，更爇龙涎饼。"]},{"t":"海棠春 其四 夜坐","f":"古风","c":["空阶碎滴芭蕉雨。","听叶叶、愁和砧杵。","剪泪问灯花，泪落花无语。","夜寒还倩飞鸿去。","空望断、天边河鼓。","暗忆碧窗南，玉柄同挥麈。"]},{"t":"桃源忆故人 寄忆","f":"古风","c":["春寒泪滴罗衾暖。","料峭湘帘初捲。","昨夜玉人窗畔。","悄悄闻低唤。","寻思却是天涯远。","此际柔肠千转。","便有南归鱼雁。","极目关河断。"]},{"t":"锦堂春 饮史子蒙晚香亭","f":"古风","c":["盆种珊瑚作串，篱编茉莉成丛。","穷冬桃李争春色，花影漾帘栊。","椰子杯浓泛绿，荔枝蜜渍生红。","别来莫问家园事，细说岭南风。"]},{"t":"三字令 其一 贞娘墓","f":"古风","c":["云悄悄，灯荧荧。","雨泠泠。","凭吊处，惜娉婷。","烟为鬟，雾为鬓，归无形。","幽篁碧，晚枫青。","恨千龄。","玉箫歇，寒蛩鸣。","辛夷襦，芙蓉席，飞残萤。"]},{"t":"三字令 其二 闺怨，集唐词","f":"古风","c":["香阁掩，泣残红。","绿阴浓。","花淡薄，月朦胧。","人去去，云杳杳，恨忡忡。","空相忆，画楼东。","此时逢。","消息远，锦书通。","万般心，千点泪，一时封。"]},{"t":"朝中措 题张真人鹤归亭，用欧公韵","f":"古风","c":["当年虚靖已凌空。","胜迹古亭中。","萝洞昼栖云雾，石坛时响松风。","每闻猿啸，惊飞鹤驾，暮鼓晨钟。","便有药炉丹井，尘湖几见仙翁。"]},{"t":"眼儿媚 秋海棠","f":"古风","c":["一帘花色写秋容。","低映碧窗红。","胭脂冷落，似颦无语，欲笑还慵。","断肠心事谁承问，旖旎不禁风。","泪痕染遍，亭亭倩影，点点芳丛。"]},{"t":"摊破浣溪沙 其一 闺情","f":"古风","c":["荡漾馀花落镜奁。","终朝唤婢镇垂帘。","私幸向来凄闷惯，只恹恹。","手划阑干私自语，髻拖针线总慵拈。","别有关心人不觉，到眉尖。"]},{"t":"摊破浣溪沙 其二 春恨","f":"古风","c":["处处风波暗未休。","晓来听雨替花忧。","想到碧窗携手地，忽凝眸。","半吐樱桃开靥晕，欲眠杨柳放眉愁。","懊恨一春憔悴甚，只如秋。"]},{"t":"喜团圆 将到家作","f":"古风","c":["依稀又见，兰陵城郭，远火垂杨。","忽逢野老偏相识，惊问鬓毛苍。","遥知窗外，柳开新眼，梅送余香。","牵衣大妇，挽须小女，争拂风霜。"]},{"t":"河渎神 题二妃庙壁","f":"古风","c":["落叶满鸣条。","柏宫方冢岧峣。","二妃遗像枕寒潮。","珠衣玉佩飘摇。","河流不向湘流绕。","泪痕此地多少。","恨与苍梧俱杳。","平阳亦有香草。"]},{"t":"醉乡春 其一 断桥月夜，同内饮荷花深处，和秦少游韵","f":"古风","c":["内外湖边人悄。","南北峰顶天晓。","摇翠盖，拥红妆，一夜幽香多少。","镜里迎风如笑。","篙底清阴堪沓。","金樽满，玉绳低，一杯共我浇苏小。"]},{"t":"醉乡春 其二 复步十锦塘，再和前韵","f":"古风","c":["波动一轮声悄。","水浸一天秋晓。","台榭冷，佩环寒，此际知心原少。","欲折柳丝低笑。","频向荷风轻舀。","香雾湿，淡烟笼，扶疏影乱痕小。"]},{"t":"阳台梦 纪梦","f":"古风","c":["个人悄倚银屏立。","唾花衣袖朦胧碧。","眼波才动已知心，笑向纱幮侧。","隔帘声暗认，低唤枕函亲切。","睡情欲上忽三更，听姊规凄咽。"]},{"t":"柳梢青 其一 杨花","f":"古风","c":["午院春深。","玉楼微度，画阁低侵。","乱捲愁来，轻沾恨去，一片伤心。","飘零幽梦难寻。","偏冷落、珠帘绣衾。","燕子争衔，罗衣暗惹，消息沉沉。"]},{"t":"柳梢青 其二 舟中偶见有感，和罗弘载韵","f":"古风","c":["无限凭栏。","一泓秋水，两点春山。","照影轻盈，盘龙新髻，青雀丫鬟。","柔枝煞是堪攀。","憨笑处、琵琶暗弹。","白草黄沙，昏鸦冷雁，曾否开颜。"]},{"t":"贺圣朝 西江送富云麓学士入都","f":"古风","c":["柳遮铃索西江路。","花唱骊驹暮。","鸾坡不借，片帆悬向，马当飞度。","连空水远举头日，近傍玉清风露。","故人天上讯狂生，只疏慵如故。"]},{"t":"茶瓶儿 王半焽江楼留饮岕线","f":"古风","c":["新制凌家岕线。","碾玉尘、月团千片。","倾琼蕊色香兼擅。","映入幽兰葱茜。","寒泉溅、乳花泫。","冰瓷春满。","松风小啜过阳羡。","月冷空、江声断。"]},{"t":"少年游 江楼秋怀，和柳屯田韵","f":"古风","c":["十年旧事上心头。","残月下江楼。","玉露初零，金风乍起，吹动一天愁。","衣香手粉曾留处，仿佛忆同游。","眼泪如潮，枕痕似水，终夜尽情流。"]},{"t":"偷声木兰花 其一 崧台岁暮，题家书尾，寄闺人","f":"古风","c":["碧桃花发人离别。","匆匆又见花时节。","细数花前。","恰值花开未一年。","惊心蜡尽逢春暮。","朔雪严风春里度。","屈指春光。","轻暖轻寒到艳阳。"]},{"t":"偷声木兰花 其二 崧台岁暮，题家书尾，寄闺人","f":"古风","c":["去年笠泽浮家去。","缥缈莫釐卿共住。","杨柳丝丝。","满箧登楼唱和诗。","而今零落荆钗伴。","憔悴罗襟红泪满。","地阔天长。","蛮雨蛮烟总断肠。"]},{"t":"偷声木兰花 其三 崧台岁暮，题家书尾，寄闺人","f":"古风","c":["长江渺渺芙蓉渡。","横浦重重梅岭路。","万水千山。","唱尽新词行路难。","海南霜雪从无信。","点点偏催游子鬓。","玉臂云鬟。","懊恼三秋人未还。"]},{"t":"偷声木兰花 其四 崧台岁暮，题家书尾，寄闺人","f":"古风","c":["男儿意气差无苦。","累汝兼持门与户。","典尽空箱。","泪裹珍珠仔细藏。","遥闻薄产丰年熟。","来岁官逋先赋足。","事事关心。","别有关心愁更深。"]},{"t":"偷声木兰花 其五 崧台岁暮，题家书尾，寄闺人","f":"古风","c":["迢迢客路谁为主，纵是在家如逆旅。","飘泊天涯。","谁道天涯胜似家。","一年暂别休悲涕。","暂别百年能有几。","此后归来。","老我柔乡傍镜台。"]},{"t":"西江月 其一 过苏秦故里","f":"古风","c":["不是秦邦金尽，那能赵印功高。","揣摩欲过洛阳桥，富贵徒欺妻嫂。","箧里阴符羞看，夜深刺股徒劳。","青溪休说寿松乔，笑尔车中难保。"]},{"t":"西江月 其二 携家宿南涧山房","f":"古风","c":["照处石泉晓镜，捲时山月帘钩。","隔窗小婢侍梳头。","不语暗垂红袖。","细听枝间唤妇，相随竹里登楼。","布帆影漾绿杨舟。","昨夜溪边泛酒。"]},{"t":"满宫花 其一 酴醾","f":"古风","c":["绿阴垂，鲛帕展。","满架浓香开遍。","凭栏索笑倩人扶，斗帐流苏初捲。","玉容娇，檀晕浅。","睡起日高犹倦。","不禁酒力不禁风，消得一枝春软。"]},{"t":"满宫花 其二 送春，集唐词","f":"古风","c":["春欲暮，遥相顾。","花暗柳浓何处。","西风回首不胜悲，帘捲晚天疏雨。","春已去，颦不语。","双鬓翠霞金缕。","旧欢新梦觉来时，泪滴枕檀无数。"]},{"t":"应天长 其一 秋闺，集唐词","f":"古风","c":["玉京人去秋萧索。","愁眉敛翠春烟薄。","倚兰桡，捲珠箔。","前事岂堪重想着。","酒醒情怀恶。","灯背小窗高阁。","离魂何处飘泊。","柳阴烟漠漠。"]},{"t":"应天长 其二 闺人刺绣，和王阮亭先生韵","f":"古风","c":["水精帘捲东风院。","枝上流莺声百啭。","绿窗轻，香梦软。","清泪朝朝曾洗面。","砌痕深，花样浅。","出水芙蕖波溅。","绣到鸳鸯偏倦。","恼乱针和线。"]},{"t":"惜分飞 胆瓶中梅菊","f":"古风","c":["冬尽平芜芳草绿。","开到春梅秋菊。","黄白新妆束。","亭亭一样人如玉。","淡月横斜疑影独。","却伴晚霜高躅。","风味看俱足。","林逋合傍陶潜宿。"]},{"t":"忆汉月 岭南芭蕉","f":"古风","c":["终岁青青如许。","结就累累堪数。","绿阴满地绿天田，种熟万千丝缕。","细把愁心展，费几夜、春情机杼。","故乡风动北窗时，更著蕉衣销暑。"]},{"t":"月中行 春情，和周清真韵","f":"古风","c":["葡萄斟满晕流红。","初卸蜡光融。","游丝轻惹罥雕栊。","冷露湿金虫。","褪残花事春归去，消几度残月疏钟。","罗裙微动骂东风。","小立画屏中。"]},{"t":"滴滴金 咏腊梅花","f":"古风","c":["玉人栀貌天然别。","换冰肌，涂娇额。","磬口檀心两奇绝。","映东篱颜色。","移来真蜡霜姿洁。","点酡酥，酿蜂蜜。","暖癸幽香擅冬日，逗春工消息。"]},{"t":"思越人 杜圻寻范少伯宅","f":"古风","c":["笠湖滨，包山麓，人传一舸西施。","消夏湾头曾醉倚，同游羞杀鸱夷。","黄金铸就谁堪羡。","霸越平吴功显。","纵是计然三策善。","独嗟爱子难免。"]},{"t":"思远人 得闲信，和晏小山韵","f":"古风","c":["劈开双鲤妆台信，报与平安客。","相思一点，伤心两字，远寄何由得。","东风泪裹珍珠滴。","和入乌丝墨。","染处忽惊红，似浓如淡，映桃花笺色。"]},{"t":"南柯子 春闺","f":"古风","c":["柳影笼蛛网。","蕉阴映绮窗。","朝晖错认是残阳。","又是一番残梦，费思量。","清镜慵开匣，青衫慢爇香。","惊魂风里絮悠扬。","恰趁花间蝴蝶，过东墙。"]},{"t":"醉红妆 灯夜纪艳","f":"古风","c":["相携女伴怯风凉。","欲添衣，又进房。","朝来新样绣鞋帮。","更换着，是谁长。","就中眉鬓独窥郎。","狂眼看，一时忙。","拾得玉彄犀合子，难暗认，试猜详。"]},{"t":"青门引 咏玉茎兰","f":"古风","c":["九畹芳菲节。","绿玉丛中堆雪。","湘潭月冷楚烟微，嫣然独对，不遣遗芳歇。","看来啼眼幽姿洁。","香色都清绝。","粉痕欲印翠袖，轻携一笑佳人折。"]},{"t":"醉花阴 九日饮豫章城楼，和李清照重阳韵","f":"古风","c":["城隅渌水明于画。","烟霭笼晴兽。","无恙是黄花，不奈西风，吹入征衫透。","一樽那管身前后。","好挹浮丘袖。","莫更去登高，满眼江山，赚得人清瘦。"]},{"t":"玉团儿 咏猫","f":"古风","c":["深闺驯绕闲时节，卧花茵，香团白雪，爪住湘裙，回身欲捕，绣成双蝶。","春来更惹人怜惜，怪无端、鱼羹虚设。","暗响金铃，乱翻鸳瓦，把人抛撒。"]},{"t":"寻芳草 咏草","f":"古风","c":["深院望王孙，看几处、平芜春草。","正萋萋、南浦西堂悄。","苔痕印、湘裙扫。","绿遍短长亭，断送尽、行人多少。","共愁生、一夜如丝绕。","芳茵外、东风晓。"]},{"t":"怨王孙 春闺雪夜，和李清照韵二首 其一","f":"古风","c":["钟静香悄。","酒欺花恼。","疏竹轻巧，琐窗洞晓。","倦倚兽炭围红。","隔帘风。","撒盐萦絮弥漫处。","吹春去。","似把青春负。","最爱玲珑，纤软仿佛轻云。","共文君。"]},{"t":"怨王孙 春闺雪夜，和李清照韵二首 其二","f":"古风","c":["玉楼初晚。","银篝小院。","著处魂消，偎时梦断。","相对郢曲难传。","话缠绵。","湔裙时节偏萦惹。","将侬舍。","恰又愁来也。","无恨伤春，情性整整斜斜。","乱杨花。"]},{"t":"江月晃重山 月下江行","f":"古风","c":["楚尾平铺银浪，吴头稳挂轻帆。","江波不动镜光涵。","推蓬望，清露湿征衫。","树色遥提影翠，山容漱水挼蓝。","六朝如梦鸟呢喃。","模糊处，回首忆江南。"]},{"t":"杏花天 咏千叶杏花","f":"古风","c":["千丝雨湿东风剪。","短墙外、红轻翠软。","绛绡重叠胭脂浅。","艳夺桃花人面。","倚云栽、日边开遍。","和笑折、明霞舒卷。","一枝妒杀红儿见。","沽酒这家庭院。"]},{"t":"浪淘沙 七夕 新月一弓弯，乌鹊桥圜，云帡缥缈度银湾。天上恐无莲漏滴，忘却更残","f":"古风","c":["莫为见时难，锦泪潸潸。","有人犹自独凭阑。","若果一年真一度，还胜人间。"]},{"t":"摘红英 美人饲金鱼","f":"古风","c":["晴光漏。","清阴昼。","风吹细縠双纹皱。","春波影，秋波映。","一片香云，游鱼惯认。","横钗溜。","连钱覆。","殷勤粉饵烦纤手。","波痕定。","波心并。","嗔郎惊散，邀郎闲凭。"]},{"t":"风马儿 秋闺","f":"古风","c":["悲哉秋气夜寥寥。","奈风又潇潇。","雨又潇潇。","欹枕孤帏，虚度可怜宵。","迢迢。","惊闻雁阵影嘹嘹。","更灯影摇摇。","竹影摇摇。","千里关山，著处梦魂飘。","朝朝。"]},{"t":"双调望江南 西湖曲十首 其一","f":"古风","c":["湖上水，风起浪纹平。","几叶丝垂鹅子淡，半篙烟染鸭头清。","镜里放船行。","珠帘捲，初映晓妆成。","翠聚两峰眉黛簇，碧含一水眼波明。","荇藻更交横。"]},{"t":"双调望江南 西湖曲十首 其二","f":"古风","c":["湖上月，风露满身幽。","银汉直垂千顷碧，琉璃冷浸一天秋。","长啸倚楼头。","三潭好，辍棹且夷犹。","弄影欲骑鹏翼去，清光偏共酒樽留。","易值此宵不。"]},{"t":"双调望江南 西湖曲十首 其三","f":"古风","c":["湖上柳，低傍六桥移。","罗幔暗窥慵望眼，画帘高捲细舒眉。","玉笛不胜吹。","谁攀折，才起欲眠时。","乱掷莺梭惊两两，轻翻燕剪几丝丝。","肠断柳枝词。"]},{"t":"双调望江南 西湖曲十首 其四","f":"古风","c":["湖上花，掩映绿窗纱。","曲院风摇仙子步，苏堤春醉美人家。","烂漫自交加。","堪竞赏，开遍海棠花。","晓起一枝和露折，午阴几树带溪斜。","十里灿晴霞。"]},{"t":"双调望江南 西湖曲十首 其五","f":"古风","c":["湖上女，三五唤同群。","浮渲梳头花样髻，轻拖窣地月华裙。","低拜岳王坟。","回步屧，敛袂向湖滨。","力怯却嫌夫婿隔，路欹微向侍儿嗔。","宜笑总宜颦。"]},{"t":"双调望江南 西湖曲十首 其六","f":"古风","c":["湖上草，漠漠复迢迢。","绣陌浓铺罗绮席，香尘暗惹绿裙腰。","凭遍木兰桡。","寒食近，第一映波桥。","斜影铁嘶金勒动，泪痕珠送纸钱烧。","著处梦魂消。"]},{"t":"双调望江南 西湖曲十首 其七","f":"古风","c":["湖上雨，景色淡空濛。","几处楼台迷倒影，满溪烟树失高峰。","曲港小船通。","西泠路，千涧响淙淙。","破竹泉高天界水，翻经声和上方钟。","游屐片云封。"]},{"t":"双调望江南 西湖曲十首 其八","f":"古风","c":["湖上舫，红粉漾晴空。","绣幕微褰清影里，纱窗半启碧波中。","小泊断桥东。","凭栏望，心事暗惺忪。","六曲银屏妆镜晓，一帘春水黛痕浓。","摇入藕花丛。"]},{"t":"双调望江南 西湖曲十首 其九","f":"古风","c":["湖上酒，日带杖头钱。","竹叶杯浮桃叶伎，梨花春酿杏花天。","一醉酒家眠。","停觞处，珍重客中餐。","底事沉吟又如笑，几回温却又重寒。","愁绪忽漫漫。"]},{"t":"双调望江南 西湖曲十首 其十","f":"古风","c":["湖上雪，六出正弥漫。","白尽青山绿鬓改，银装琼砌玉楼寒。","翠袖倚栏杆。","乘兴去，凄断六桥湾。","苏小梦迷油壁杳，林逋魂绕暗香闲。","斜湿酒旗还。"]},{"t":"芳草渡 松陵舟中送别","f":"古风","c":["吴江碧，吴山青。","兰风起，满洞庭。","骊歌愁绝不堪听。","从兹去，郎乘马，妾扬舲。","还则愿。","尘吹转。","辙迹随郎近远。","怀明月，指双星。","相向冥。","郎抱影。","妾倚形。"]},{"t":"金凤钩 咏绣鞋","f":"古风","c":["昨宵绣，幕曾近。","怪花底、湘帘初褪。","纤如钩月，柔如削玉，掌上看来越韵。","莲踪一捻莲痕印。","向洛浦、香尘微衬。","双双綵雀，盈盈罗袜，稳称凌波身分。"]},{"t":"鹧鸪天 其一 灯前花影","f":"古风","c":["醒写精神醉写容。","柔枝无力倚帘栊。","衬将皓月分肥瘦，笼得轻烟别淡浓。","青镜畔，碧纱中。","兰膏烧彻转玲珑。","欲教移入罗帏里，好把红缸照院东。"]},{"t":"鹧鸪天 其二 月下灯花","f":"古风","c":["金波滟滟玉缸融。","碧蕊离离白路浓。","笑剔芳心凝兔影，暗添喜色映蟾宫。","银汉北，画堂东。","花开偏照百花丛。","嫦娥此夜休垂泪，落尽垂珠一穗中。"]},{"t":"鹧鸪天 其一 闻鹧鸪","f":"古风","c":["楚水吴山何限情。","透花窥鸟最分明。","惟奈瘴烟笼饮啄，亦悔梅岭阻归程。","一片雨，五音清。","无那春风欲送行。","秦人只解歌为曲，歌按秦楼梦不成。"]},{"t":"鹧鸪天 其二 春闺","f":"古风","c":["弱柳千条杏一枝。","已凉天气未寒时。","故将别泪和乡泪，莫遣佳期更后期。","两不见，暗相思。","浅深更漏妾偏知。","低头闷把衣襟撚，为报春风且莫吹。"]},{"t":"鹧鸪天 其三 春情","f":"古风","c":["远客辞家月再圆。","绿杨如发雨如烟。","梁间燕子闻长叹，楼上花枝照独眠。","兴又寝，倚阑干。","各自当情各自欢。","回身泣向寥天月，恰漏清光落枕边。"]},{"t":"鹧鸪天 其四 秋闺","f":"古风","c":["山槛晴归漠漠烟。","绿窗红泪冷涓涓。","长疑好事皆虚事，可得潸然是偶然。","兰烛烬，江波连。","当时惆怅不曾眠。","起来自擘纱窗破，病眼开时月正圆。"]},{"t":"鹧鸪天 其五 即席","f":"古风","c":["莫怪频频上此台。","翠萝深处遍苍苔。","能令瀑水清人境，更取峰霞入酒杯。","堤柳动，野荭开。","林下轻风待落梅。","从来此地黄昏散，往事空成半醉来。"]},{"t":"玉楼春 其一 春怀","f":"七言律诗","c":["丈夫飘荡今如此。","更上江楼望江水。","论交却忆十年时，怀袖未消三岁字。","江柳影寒新雨地。","无限幽芳徒欲寄。","二月春风最断肠，一梦不须追往事。"]},{"t":"玉楼春 其二 忆故园诸友","f":"七言律诗","c":["闻道毗陵诗酒兴。","何事经年断书信。","相期共斗管弦来，今日知音一留听。","玉漏声长灯耿耿。","星汉渐移庭竹影。","寒林晓际别生春，暗数残更不成寝。"]},{"t":"玉楼春 其三 春情","f":"七言律诗","c":["帘捲青山巫峡晓。","红艳影多风袅袅。","今日残花昨日开，月色更添春色好。","蝴蝶晴连池岸草。","客枕幽单看春老。","夜深微雨醉初醒，惆怅旧游无复到。"]},{"t":"玉楼春 其四 春怨","f":"七言律诗","c":["年年纵有春风便。","楚竹离声为君变。","点破繁华四五枝，零落胭脂两三片。","未解多情梦梁殿。","几度相思不相见。","为他人作嫁衣裳，粉泪凝珠滴红线。"]},{"t":"玉楼春 其五 秋村","f":"七言律诗","c":["日暮东风芳草绿。","衰柳寒芜绕茅屋。","百树鸡桑半顷麻，数尺丝纶一竿竹。","此处挂冠凉自足。","黄菊倚风村酒熟。","有时新月傍帘钩，唱到白蘋洲畔曲。"]},{"t":"玉楼春 其六 山行有怀","f":"七言律诗","c":["京邑旧游劳梦想。","中岳深林人独往。","数村残照半岩阴，十亩春蔬一藜杖。","一度相思一惆怅。","心在君家辘轳上。","随风好去落谁家，杨柳败梢飞叶响。"]},{"t":"瑞鹧鸪 闺情，集唐诗","f":"七言律诗","c":["日照深红几树丝。","只应闲看一枝枝。","孤溪月满维舟夜，分隔休灯灭烛时。","多为过防成后悔，谁怜梦好转相思。","纤腰舞尽春杨柳，惟有春风仔细知。"]},{"t":"瑞鹧鸪 其一 赋得春雪梅花，和东坡韵","f":"七言律诗","c":["元辰稷雪雨廉纤。","春色寒威分外严。","冷蕊半成云母树，冰盘疑贮水晶盐。","集衣似觉凝香艳，索笑还宜卧画檐。","不道笛中歌一曲，东风吹彻万山尖。"]},{"t":"瑞鹧鸪 其二 赋得春雪梅花，和东坡韵","f":"七言律诗","c":["寒光初积暗金鸦。","九陌争传咏雪车。","上苑有香堪共影，群山无数独开花。","黄昏月动王恭氅，缟带烟迷苏小家。","应是争春梅雪共，广平新赋手频叉。"]},{"t":"瑞鹧鸪 其三 赋得春雪梅花，和东坡韵","f":"七言律诗","c":["仙人剪水合秾纤。","洒竹侵松势更严。","入户只应飞玉女，卷帘讵是刻无盐。","孤根欲暖霜滋晓，五出无尘月挂檐。","何事满空飘瑞叶，一枝斜压还峰尖。"]},{"t":"瑞鹧鸪 其四 赋得春雪梅花，和东坡韵","f":"七言律诗","c":["涂窗谁识暮栖鸦。","和雨和烟畏日车。","春到江南花是雪，月残辽海雪成花。","天因不夜银千顷，水更无声玉万家。","便使剡溪乘兴去，横枝遥见酒旗叉。"]},{"t":"南乡子 秋闺月夜","f":"古风","c":["极目海天空。","碾就冰轮照碧峰。","渐有清光穿入户，玲珑。","玉臂云鬟素影中。","独自倚梧桐。","怅望银河待好风。","夜半若随千里梦，相逢。","皎洁随君处处同。"]},{"t":"南乡子 其一 下第别诸同年出都","f":"古风","c":["春别洛阳城，又见新书甲乙名。","国器旧知收片玉，登瀛。","历历银钩指下生。","斜月入前楹。","心仰莲峰望太清。","春色年来谁是主，无成。","半在云霄觉更荣。"]},{"t":"南乡子 其二 西归道中","f":"古风","c":["残月下寒沙。","北斗阑干南斗斜。","千里不辞行路远，天涯。","独自狂夫不忆家。","何处得停车。","又见秦城换物华。","白雪却嫌春色晚，飞花。","深掩虚窗卧碧纱。"]},{"t":"南乡子 其三 送金明府归里","f":"古风","c":["文苑振金声。","竹绕琴堂水绕城。","愿以深心留善政，高名。","朝野咸推重太平。","县鼓应鸡鸣。","桥上春风绿野明。","若使巢由同此意，簪缨。","笑引江帆带月行。"]},{"t":"南乡子 其四 旅馆对月","f":"古风","c":["月色白如霜。","一片山花落笔床。","检得旧书三四纸，成行。","惟到樽前似故乡。","不是少清光。","依旧明朝在路旁。","莫道蓟门秋信少，衡阳。","转觉愁随夜夜长。"]},{"t":"南乡子 其五 闺情","f":"古风","c":["归棹隐孤舟。","水带离声入梦流。","锦字织成添别恨，悠悠。","笑摘青梅叫阿侯。","红烛乍迎秋。","风物凄凄宿雨收。","山色正来衔小苑，高楼。","莫向银台半夜游。"]},{"t":"南乡子 其六 闺思","f":"古风","c":["谷鸟一声幽。","莫遣杨花笑白头。","先向红妆添晓梦，新愁。","云物凄清拂曙流。","共作草堂游。","次第看花直到秋。","况是故园摇落夜，登楼。","罗绮晴骄绿水洲。"]},{"t":"南乡子 其七 少年行","f":"古风","c":["惊起欲栖乌。","骏马翩翩新虎符。","五凤街头闲勒辔，金吾。","犹暇怜诗爱酒无。","渺渺戍烟孤。","笑倚春风杖辘轳。","相忆杏花坛上去，樗蒲。","只有挼莎更一呼。"]},{"t":"南乡子 其八 旅怀","f":"古风","c":["江静晚烟浓。","二十年来万事同。","夜半酒醒人不觉，秋风。","晓月当帘挂玉弓。","不复旧时容。","砚匣留尘尽日封。","汉水楚云千万里，无穷。","半在邯郸驿树中。"]},{"t":"南乡子 其九 春兴","f":"古风","c":["岚翠湿人衣。","或棹轻舟或杖藜。","一院落花无客醉，莺啼。","逸处能高怨处低。","夜妒燕双栖。","回看池塘影渐稀。","唯有教坊南畔草，萋萋。","空使王孙见即迷。"]},{"t":"南乡子 其十 春情","f":"古风","c":["更遣几年回。","石径春风长绿苔。","此夜断肠人不见，徘徊。","昨夜缘何入梦来。","江上落残梅。","莫惜芳时醉酒杯。","心似百花开未得，春催。","坐对寒松手自栽。"]},{"t":"南乡子 其十一 春雪早行","f":"古风","c":["莫道梦魂遥。","六出飞花处处飘。","独倚破帘闲怅望，春朝。","雪满长安酒价高。","跃马上河桥。","菰叶风翻绿剪刀。","为近都门多送别，长条。","力不禁风旋旋销。"]},{"t":"南乡子 其十二 秋日遣兴","f":"古风","c":["乘兴且长歌。","身外功名一任他。","自欲放怀犹未得，如何。","寂历秋花野意多。","芳草渐成窠。","镜水无风也自波。","纵有邻人解吹笛，谁过。","空苑凫鹥占浅莎。"]},{"t":"南乡子 其十三 秋感","f":"古风","c":["香桂折新柯。","紫陌金堤映绮罗。","莫是长安行乐地，蹉跎。","旧路依然此重过。","顾影逗轻波。","到处闲门长薜萝。","休唱开元供奉曲，无多。","落叶纷纷暮雨和。"]},{"t":"南乡子 其十四 西江岁暮，送友入都","f":"古风","c":["相亿一欣然。","何处韶光最可怜。","别后依依寒食里，东田。","沙岸蒲帆隔野烟。","湓水暮连天。","愁见孤城落日边。","共说京华旧游地，潸然。","明日春风又一年。"]},{"t":"南乡子 其十五 春闺即事","f":"古风","c":["长望涕沾巾，深院无人独倚门。","惆怅春归留不得，黄昏。","静夜名香手自焚。","邀我对芳樽。","蝉翅低从两鬓分。","唯有风光与踪迹，销魂。","图遗萧郎问泪痕。"]},{"t":"南乡子 其十六 闻鹧鸪","f":"古风","c":["格磔鹧鸪啼。","暖戏平芜锦翼齐。","日晚长烟高岸近，峰低。","苦竹岭头人未归。","此路不堪迷。","一向南飞又北飞。","惆怅一年春又去，依依。","莫动哀吟易惨凄。"]},{"t":"南乡子 其十七 病起读庄子","f":"古风","c":["俯首视烟霞。","云蔽长安路更赊。","藜杖移时挑细药，幽花。","洞口人家日易斜。","不得问丹砂。","席上馀杯对早茶。","销得人间无限事，南华。","斗觉霜毛一半加。"]},{"t":"南乡子 其一 江楼","f":"古风","c":["飒飒鬓毛苍。","北望伤神坐北窗。","厚禄故人书断绝，凄凉。","日满楼前江雾黄。","恩岂布衣忘。","青史无劳数赵张。","虚阁卷帘图画里，潇湘。","指点银瓶索酒尝。"]},{"t":"南乡子 其二 送友","f":"古风","c":["春色泪痕边。","日短江湖白发前。","锦席淹留还出浦，回船。","忽漫相逢是别筵。","万一故人怜。","老去新诗谁与传。","古往今来皆涕泪，风烟。","信有人间行路难。"]},{"t":"南乡子 其三 南归，遇北来友人","f":"古风","c":["容易失沉沦。","路难悠悠常傍人。","不为困穷宁有此，须亲。","白水青山空复春。","对酒满壶频。","户牖凭高发兴新。","正是江南好风景，逢君。","更恐归飞隔暮云。"]},{"t":"南乡子 其一 微泉阁遣怀，呈家叔","f":"古风","c":["倚杖小池边。","半采红莲半白莲。","辜负春风杨柳曲，今年。","犹有些些旧管弦。","相对一陶然。","半醉行歌半坐禅。","绿竹挂衣凉处歇，时眠。","免被饥寒婚嫁牵。"]},{"t":"南乡子 其二 秋日怀友","f":"古风","c":["非病亦非眠。","况是秋阴欲雨天。","惟觅少年心不得，依然。","老后谁能惜酒钱。","久结静中缘。","满地槐花满树蝉。","何处曾经同望月，堂前。","池畔犹应泊旧船。"]},{"t":"南乡子 闺情，集李义山句","f":"古风","c":["恼带拂鸳鸯。","又入卢家妒玉堂。","见我佯羞频照影，游郎。","不信年华有断肠。","金斗熨沉香。","玉殿秋来夜正长。","直道相思了无益，轻狂。","欲拂尘时簟竟床。"]},{"t":"南乡子 其一 春闺","f":"古风","c":["鹦鹉伴人愁。","情绪牵人不自由。","正是落花寒食夜，南楼。","半镜随郎葬杜邮。","敛笑慢回头。","韩寿香焦亦任偷。","此际别人应未觉，风流。","眼意心期卒未休。"]},{"t":"南乡子 其二 闺情","f":"古风","c":["闲画两鸳鸯。","院宇秋明日日长。","蜀纸麝煤沾笔兴，茶香。","懒对菱花晕晓妆。","怯见上空床。","半夜潜身入洞房。","光景旋销惆怅在，凄凉。","风月应知暗断肠。"]},{"t":"虞美人 其一 本意","f":"楚辞体","c":["霜花溅血乌江路。","的是君王误。","鸿门玉斗怪当年。","不教虞兮舞剑、向樽前。","芳魂随向江东渡。","犹作花枝舞。","彘也堪怜雉也妖。","笑问汉王遗恨、几时消。"]},{"t":"虞美人 其二 过虞姬墓","f":"楚辞体","c":["孤坟遥枕荒祠右。","过客频回首。","帐中夜舞不胜情。","化作千年舞草、尚如生。","八千祗有虞兮在。","儿女英雄槩。","刘郎宫寝付寒烟。","留取美人黄土、大王前。"]},{"t":"虞美人 其一 闺情","f":"古风","c":["玉炉香暖频添炷。","起坐浑无绪。","堕阶萦藓舞愁红。","薄晚春寒无奈、落花风。","楼高不见章台路。","更引流莺妒。","数声和月到帘栊。","惊破碧窗残梦、花屏空。"]},{"t":"虞美人 其二 闺恨","f":"古风","c":["南园满地堆轻絮。","梁燕双来去。","归时休照烛花红。","楼上月明三五、琐窗中。","好是向人柔弱处。","一梦云兼雨。","觉来枕畔怯晨钟。","还是去年今日、恨应同。"]},{"t":"虞美人 其三 春情","f":"古风","c":["已知前事无寻处。","春恨如何去。","晓莺帘外语花枝。","说尽人间天上、两心知。","枕上夜长长似岁。","思梦时时醒。","越罗衣褪郁金黄。","髻慢钗横无力、纵猖狂。"]},{"t":"春去也 春愁","f":"古风","c":["春来风雨侬愁做。","送得春归，却是愁来路。","愁来原是共春来，春归不带愁同去。","愁欲留春少驻。","春竟抛愁独去。","何如索性不逢春，一年长在愁边住。"]},{"t":"鹊桥仙 其一 七夕柬范龙仙","f":"古风","c":["蛛丝暗卜，綵线频穿，此夜倚栏多少。","纵教痴绝似牵牛，偏消受、天孙机巧。","百子池边，长生殿里，一点梦魂难到。","被驱原只为逋钱，料天也、应须一笑。"]},{"t":"鹊桥仙 其二 舟夕口占，赠萧北江","f":"古风","c":["文园妙手，词坛骏足，兼擅谁如卿者。","横吹铁笛问婵娟，又何减、君家思话。","弦歌城外，射书濠畔，到处溪山如画。","凭阑永夜听清谈，看亹亹、从天而下。"]},{"t":"夜行船 其一 咏萤","f":"古风","c":["露冷纱窗梧影暗。","却数点、疏星零乱。","叶底轻沾，花梢低映，长向琴书作伴。","飞上钗梁云影畔。","偏照出、晚妆娇情。","带雨才来，随风忽去，恐惹多情纨扇。"]},{"t":"夜行船 其二 咏萤","f":"古风","c":["一点丹良秪自抱。","休浪说、宵行熠耀。","微时能化，幽处偏明，敢向纤阿争耀。","三十六宫曾误到。","悔误作、隋宫腐草。","漂泊年年，流辉耿耿，摇弄客床残照。"]},{"t":"醉落魄 秋夜","f":"古风","c":["竹摇月碎。","一声破柝惊初睡。","瑟瑟秋风欺薄醉。","断雁寒螀，催促人憔悴。","遍将往事思量。","再安排几度浑无奈。","谁道玉楼人不在。","夜夜寻侬，稳坐心儿内。"]},{"t":"一斛珠 闺戏","f":"古风","c":["鸟歌花舞。","倦人天气槐阴午。","闷来自照春山膴。","却有谁过，花下呼鹦鹉。","女伴相携人四五。","斗完芳草翻棋谱。","憨时笑拔金钗赌。","些事关心，输却钗双股。"]},{"t":"小重山 花下","f":"古风","c":["晓起相携花下嫣。","折来和露插、乱云边。","绕身一步更堪怜。","还却立，故向侍儿前。","分手各凄然。","百花生日日、恨年年。","落花如雨雨如烟。","关心记，好梦总难全。"]},{"t":"踏莎行 新燕","f":"古风","c":["杏苑烟稠，梨亭云软。","凭栏一望春尘远。","去年燕子定归来，风前试把帘儿捲。","约约双飞，生生细剪。","商量似说春巢浅。","初来不为哺雏忙，经时才见衔泥转。"]},{"t":"惜分钗 美人藏钩","f":"古风","c":["梨云榭。","梧阴下。","翠袖娟娟凉月夜。","近瑶台。","映金罍。","鹅儿酒满，钩弋拳开。","猜。","猜。","张灯灺。","分曹射。","暗动横波鬟影泻。","故迟徊。","更佯推。","被侬单算，轮与双枚。","杯。","杯。"]},{"t":"七娘子 过露箸祠","f":"古风","c":["平湖捲起寒波泻。","淡烟吹散横塘洒。","五夜冰心，千年玉骨。","几人巾帼如卿者。","停桡试问灵旗下。","拂衣争向题诗罢。","燕子不来，棠梨欲谢。","芳魂今日犹生也。"]},{"t":"东坡引 其一 手镜","f":"古风","c":["清光憔悴久。","情绪消磨有。","菱花新样频携手。","泪痕犹在否。","泪痕犹在否。","从郎别后。","时时昏黝。","长只共夫人争瘦。","团圆两字今番又。","相依堪白首。","相依堪白首。"]},{"t":"东坡引 其二 剪刀","f":"古风","c":["绣奁晴色换。","飞絮东风满。","郎来好试并州看。","情丝千种乱。","情丝千种乱。","夜深频放，有愁相伴。","共画阁玉人春倦。","朦胧一缕裁难断。","双鸳谁剪半。","双鸳谁剪半。"]},{"t":"东坡引 其三 琢针","f":"古风","c":["夜来能暗认。","乞巧谁能信。","琢成双眼锋芒迅。","漫将丝线引。","漫将丝线引。","欲吞如刺，啼痕隐隐。","敢辜负粉郎私赠。","临行曾记郎衣准。","归来还自忖。","归来还自忖。"]},{"t":"东坡引 其四 纽扣","f":"古风","c":["暖金云影溜。","綵缕芙蓉绣。","端溪新致丁香扣。","怜伊清影瘦。","怜伊清影瘦。","罗襦半解，那时时候。","只两点横波晕透。","朝来牢系鸳鸯纽。","莫教消息漏。","莫教消息漏。"]},{"t":"东坡引 其五 漆枕","f":"古风","c":["红蕤光欲耀。","紫树云争绕。","携来岭海邯郸道。","得人怜惜早。","得人怜惜早。","玉绳低处，罗帷未晓。","却此际情深多少。","从今消受檀郎抱。","一宵残梦了。","一宵残梦了。"]},{"t":"东坡引 其六 藤席","f":"古风","c":["滑如霜薤叶。","细似湘纹节。","琉璃黄映消肌雪。","匡床凭拂拭。","匡床凭拂拭。","孤眠此夜，偏生欹仄。","较不似昨宵宁贴。","思量几度重铺设。","与郎随转侧。","与郎随转侧。"]},{"t":"临江仙 其一 过百花洲怀古，用鹿虔扆韵","f":"古风","c":["独向百花洲上望，凄迷衰草连空。","鸡城貕巷杳无踪。","几丝杨柳，摇漾锦帆风。","只有胥江江畔水，潺潺犹响吴宫。","不教流入粉塘中。","数声清磬，细雨带轻红。"]},{"t":"临江仙 其二 半圃","f":"古风","c":["半捲半垂帘幕，半村半郭人家。","半开半落野棠花。","半床堆古画，半碗试新茶。","半树老藤夭娇，半间野屋横斜。","平分春半半春华。","半樽凭醒醉，半枕足生涯。"]},{"t":"临江仙 其三 一亭","f":"古风","c":["一阁一亭新筑，一丘一壑都宜。","一天风月一帘知。","一窗梧影动，一榻柳阴移。","有酒一壶堪饮，有书一卷堪持。","一琴一鹤更相随。","一痴从我好，一醉任人嗤。"]},{"t":"临江仙 其四 忆丹霞之游，和澹归师寄赠韵","f":"古风","c":["一骑红尘飞昔梦，片帆两地西风。","到今怀抱小芙蓉。","出门终古望，吾党素心同。","天柱峰高仙子住，五弦目送归鸿。","锦囊词句刬虚空。","旧时烧佛处，只在晚霞中。"]},{"t":"临江仙 其五 过分水河，和王仔园韵","f":"古风","c":["终古灵奇恢禹绩，中流河渎平分。","云沙浩浩水粼粼。","黄牛如断岸，白马暗通痕。","南北维舟争报赛，九州万派知遵。","安澜直自到天津。","河清应献颂，海若尽称臣。"]},{"t":"临江仙 其一 秋晚","f":"古风","c":["客路不归秋又晚，孤舟日暮行迟。","绿潭红树影参差。","荒城临古渡，惊月练梳枝。","隔年拟待春消息，花开花谢相思。","莫愁还自有愁时。","寸心言不尽，一种乱如丝。"]},{"t":"临江仙 其二 闺忆","f":"古风","c":["好去出门休落泪，津头日日人行。","晚添山雨作江声。","几回惊妾梦，十里断孤城。","总然一夜风吹去，秋河怅望平明。","多情却恨似无情。","空馀庭草色，不遣柳条青。"]},{"t":"临江仙 其三 闺情","f":"古风","c":["闻折海棠看更撚，前欢休更思量。","小钗横戴一枝芳。","野芜平似剪，鸾镜掩休妆。","画堂昨夜西风过，银蟾影挂潇湘。","欲凭危槛恨偏长。","罗帷愁独入，红蜡泪飘香。"]},{"t":"临江仙 其四 秋闺","f":"古风","c":["因想玉郎何处去，渡头三两人家。","但凭魂梦访天涯。","愁匀红粉泪，帘捲玉钩斜。","一饷凭阑人不见，芙蓉苑里看花。","闲池初涸草侵沙。","金盘珠露滴，山掩小屏霞。"]},{"t":"临江仙 其五 集唐诗唐词","f":"古风","c":["风里落花谁是主，江潭春草萋萋。","严妆初罢啭黄鹂。","似应知妾恨，更与尽情啼。","终是疏狂留不住，与郎终日东西。","门前杨柳绿阴齐。","征帆何处客，惆怅暮云迷。"]},{"t":"蝶恋花 花朝和内","f":"古风","c":["屈指春光将过半。","又是花朝，花信春莺唤。","情绪繁花花影乱。","护花花下将花看。","拈花笑倩如花伴。","细读花间，花也应肠断。","花落花开花事换。","编成花史山妻管。"]},{"t":"蝶恋花 其一 闺情，集唐诗","f":"古风","c":["钿合钗寒龙脑冻。","衫薄香销，舞怯铢衣重。","疑是落花还碧洞。","银筝夜久殷勤弄。","愁捻银针信手缝。","翠帐云屏，一夕秋砧动。","凭仗东风好相送。","只应添得清宵梦。"]},{"t":"蝶恋花 其二 闺情，集唐诗","f":"古风","c":["白日当天三月半。","各自无聊，妆好方长叹。","紫燕衔花向庭满。","花前拭泪情无限。","衣带相思日应缓。","风雨萧萧，吹我梦魂断。","今夜偏知春气暖。","纱窗只有灯相伴。"]},{"t":"遐方怨 别情","f":"古风","c":["钗影乱，鬓云横。","五更钟易晓，一夜月偏清。","匆匆未诉别离情。","别离滋味又分明。","芳草路，短长亭。","低回千万意，将息两三声。","临行细细问郎程。","梦中还拟傍郎行。"]},{"t":"后庭宴 其一 过东皋故址","f":"古风","c":["燕麦争飞，兔葵如簇。","斜阳影外伤心目。","十年此地盛楼台，繁华一瞬惊吹烛。","几丝垂柳寒塘，稳睡双双属玉。","樵歌鱼笛，恍听当时曲。","草色月凄迷，铃声风断续。"]},{"t":"后庭宴 其二 岭南归棹苦雨，和罗弘载韵","f":"古风","c":["滚滚洪涛，潇潇暮雨。","春云遮住春归路。","片云岭外是江南，岭中尚隔千重雾。","长年稳挂轻帆，欲趁东风飞去。","滩高溜急，不放扁舟度。","共是别离人，又添肠断句。"]},{"t":"钗头凤 其一 个侬","f":"古风","c":["清光昼。","花阴覆。","个侬俏立黄昏后。","携手地。","偏经意，万千欲语，全无一字。","记。","记。","记。","红烛透。","金钗溜。","销魂又到魂销候。","柔乡味。","衣香气。","纱窗忽曙，星眸惊睇。","未。","未。","未。"]},{"t":"钗头凤 其二 纪遇","f":"古风","c":["纱窗口。","银屏后。","阿郎记得当时否。","人犹在。","期难再。","相逢蓦地，却将伊背。","悔。","悔。","悔。","心头有。","眉头皱。","樽前故故持郎酒。","欢相爱。","嗔相碍。","横波斜送，又将伊怪。","待。","待。","待。"]},{"t":"唐多令 其一 月夜代忆","f":"古风","c":["香雾湿帘栊。","长波漾碧空。","恨天涯两地难逢。","一点关山人共远，郎只在，月明中。","千里寸心通。","尺书双泪封。","好将情绪寄东风。","却恐东风吹不去，和妾梦，付归鸿。"]},{"t":"唐多令 其二 南阳道中，和王仔园韵","f":"古风","c":["岱色入青湖。","晴光漾白凫。","映芙蕖百里平铺。","似放弱耶溪畔棹，摩诘画，辋川图。","风景补方壶。","临流万派舒。","濯尘缨细鉴头颅。","偏忆故园烟水外，乘小艇，泛菱蒲。"]},{"t":"一剪梅 其一 春怨","f":"古风","c":["空闺无奈日长时。","朝也迟迟。","暮也迟迟。","春心百尺绕游丝。","草也丝丝。","柳也丝丝。","天遣多情不自持。","嗔也谁知。","喜也谁知。","一回踪迹几回思。","坐也堪思。","立也堪思。"]},{"t":"一剪梅 其二 民歌","f":"古风","c":["少年豪气欲先民。","卦有容民。","数有司民。","岂期编户作齐名。","畜我恒民。","荣我中民。","长吟陇亩一遗民。","高阳贱民。","襄阳酒民。","相忘总是葛天民。","不是尧民。","还是舜民。"]},{"t":"锦帐春 看婢绣芙蓉","f":"古风","c":["两两相扶，亭亭独立。","映渌水冯彝捧出。","影遥临、娇欲语，似若耶初入，鲛绡还湿。","綵缕千丝，银针万叠。","红潮晕、黛朱添色。","靥盈盈、情脉脉，向田田池侧。","更宜鸂鶒。"]},{"t":"系裙腰 题月华裙","f":"古风","c":["怪看窣地缕金花。","新匀染，拂轻纱。","浅深颜色随浓淡，彩晕交加。","云拖水，月生华。","五铢细熨湘纹褶，襞来皱，处偏佳。","嫦娥碧海微尘步，低映晴霞。","东风摇漾，绣屏遮。"]},{"t":"定风波 淮阴侯钓台有感","f":"古风","c":["当时国土总无双。","寂寂荒台卧夕阳。","逐鹿追猴真善斗。","奔走。","山河提取送刘郎。","不及野鸡烹国狗。","低首。","妇人谋定胜齐王。","生死皆由女子手。","谁咎。","悔教一饭重相将。"]},{"t":"渔家傲 其一 题曹雪鸿荆溪钓隐图","f":"古风","c":["曹子家居荆水畔。","一蓑烟雨堂中见。","玉洞桃花看欲遍。","谁兼擅。","磻溪写入鹅溪绢。","明月为钩虹作线。","虚舟一任频回转。","与世浮沉山水愿。","将图展。","风波此地从君便。"]},{"t":"渔家傲 其二 济上登酒楼游南池漫作，和王仔园韵","f":"古风","c":["碧柳垂丝花满树。","池楼高下任城路。","胜迹千年传李杜。","谁留住。","江山留得诗人处。","满目悲风嗟日暮。","萦阶点点飘红素。","入海莫随烟雾去。","悠然遇。","光芒万丈云天曙。"]},{"t":"渔家傲 其三 青墩月令，和欧阳公鼓子词","f":"古风","c":["正月村居梅信早。","轻澌解冻清溪绕。","影动游鱼翻荇藻。","春寒峭。","隔村几处啼春鸟。","城市喧春灯正好。","数声横笛闲庭悄。","入夜凄清圆月皎。","东风巧。","小烟弄柳晴光晓。"]},{"t":"渔家傲 其四 青墩月令，和欧阳公鼓子词","f":"古风","c":["二月风和春满院。","游丝雨歇朝寒浅。","细草平铺芳径软。","湘帘卷。","新巢絮语双双燕。","红杏倚墙开欲遍。","落梅委地香千片。","蝴蝶纷飞鶗鴃啭。","清樽劝。","日斜绣阁停针线。"]},{"t":"渔家傲 其五 青墩月令，和欧阳公鼓子词","f":"古风","c":["三月艳阳晴气候。","百花烂漫开清昼。","万紫千红铺锦绣。","携纤手。","繁香点点盈衣袖。","摇曳沿溪千树柳。","扑天飞絮春塘皱。","小艇载诗兼载酒。","桃源口。","疏林月出人归后。"]},{"t":"渔家傲 其六 青墩月令，和欧阳公鼓子词","f":"古风","c":["四月清和风景淑。","浓阴万树围新绿。","麦穗垂垂豌豆熟。","浓睡足。","黄鹂唤起惊相逐。","结子樱桃檐畔簇。","满林新笋篱边矗。","压架蔷薇花覆屋。","西溪曲。","半篙荡碎波纹縠。"]},{"t":"渔家傲 其七 青墩月令，和欧阳公鼓子词","f":"古风","c":["五月沟塍新水涨。","海榴照眼葵花放。","徙倚柴门闲策杖。","秧针漾。","平畴翠剪千层浪。","赤日场平镰架响。","黄云䆉稏人熙攘。","万点鱼苗临水饷。","层潭上。","亭亭绿柄风摇飏。"]},{"t":"渔家傲 其八 青墩月令，和欧阳公鼓子词","f":"古风","c":["六月炎蒸三伏节。","古槐日午蝉声咽。","绿水红蕖相映澈。","人清绝。","惊回午梦松风冽。","槛畔闽兰和露折。","帘间茉莉堆香雪。","浴罢晚凉吹木末。","新茗啜。","凭栏又送纤纤月。"]},{"t":"渔家傲 其九 青墩月令，和欧阳公鼓子词","f":"古风","c":["七月新凉风淡沱。","曝衣时节陈瓜果。","一叶梧桐秋色堕。","情无那。","扑萤戏对双星卧。","菱角朝搴青万朵。","鸡头手擘珠千颗。","不袜不巾乘小舸。","新雨过。","白鸥飞点溪烟破。"]},{"t":"渔家傲 其十 青墩月令，和欧阳公鼓子词","f":"古风","c":["八月风高珠露冷。","蓼红芦白装秋景。","皓魄一轮明似镜。","波光映。","空庭万顷琉璃净。","老桂吹香芳满径。","樛枝密叶晴云瞑。","夜永乱飘金粟影。","幽梦醒。","人间亦有清虚境。"]},{"t":"渔家傲 其十一 青墩月令，和欧阳公鼓子词","f":"古风","c":["九月轻霜拂商素。","纷披黄菊篱边吐。","把酒持螯斜日暮。","闲凝伫。","迷离衰草粘云树。","醉里茱萸应细数。","江山转瞬悲今古。","目断西风江上路。","登高处。","青墩旧是吴兴墓。"]},{"t":"渔家傲 其十二 青墩月令，和欧阳公鼓子词","f":"古风","c":["十月小春粳稻获。","堆场囷廪鸡声喔。","拾穗儿童争雀跃。","开缸酌。","新篘酿就田家乐。","鸦舅霜酣红灼灼。","闲花点缀丛林薄。","风急一行寒雁落。","惊剥啄。","筚门客至无人诺。"]},{"t":"渔家傲 其十三 青墩月令，和欧阳公鼓子词","f":"古风","c":["十一月履长添绣线。","如船小阁拥炉暖。","榾柮烧红浊酒满。","银烛短。","读完几上残书卷。","向晓霏霏飘雪霰。","浦银堆粉江山换。","独上鹤楼迷望眼。","人不见。","渔蓑隐约前溪岸。"]},{"t":"渔家傲 其十四 青墩月令，和欧阳公鼓子词","f":"古风","c":["十二月月穷阴遍野。","小桥曲径门低亚。","曝背茅檐朝旭晒。","真潇洒。","天然一笔营丘画。","枯树饥乌声哑哑。","匡床僵卧曾楼下。","冰箸寒凝樽懒把。","迎年夜。","灯前妻女团圞话。"]},{"t":"破阵子 有感","f":"古风","c":["老去忽思戈甲，春来欲卧沙场。","红散桃花衔紫勒，白映梨花点绿枪。","新推六郡良。","帐下惊穿虎节，军前初试鱼肠。","鹳鹤一呼金马动，鼓角千山玉案长。","横行道夜郎。"]},{"t":"金蕉叶 酬内寄新茶","f":"古风","c":["蚕房细把旗枪别。","乳花蹴起磁瓯雪。","珍重关山，曾经纤手摩挲怯。","寄与文园消渴。","泪波暗送春风隔。","含颦斜倚人愁绝。","万里归来，一枝碾破愁千结。","好共二泉同啜。"]},{"t":"青杏儿 独夜","f":"古风","c":["独自倚山楼。","孤云晚、簟縠纹流。","一天愁绪千行泪，丝丝点点，旧愁如雨，新雨如愁。","灯影怕凝眸。","人影寂、衾影还留。","雁声嘹呖蛩声怨，竹声凄切，泉声呜咽，齐到心头。"]},{"t":"苏幕遮 读倦，夜分婢进新茗，戏用王敬美韵赠之","f":"古风","c":["漏声残，蕉雨碎。","半榻灯荧，不照江郎睡。","两两双鬟偏解意。","泉响松风，剪烛添沉水。","展磁瓯，斟玉醑。","恐怕来朝，晓梦莺催起。","脉脉此情谁得似。","情胜初尝，好试春滋味。"]},{"t":"落灯风 闺情，集唐诗","f":"古风","c":["五更惆怅回孤枕，玉容惊觉浓睡醒。","梳洗懒无情，荆钗任意撩新鬓。","拂匣光临镜。","忍使芳魂愁夜永，珍珠帘外梧桐影。","天寒入剪刀，叶下绮窗银烛冷。","裁缝无处等。"]},{"t":"甘州遍 阅江楼观射，和唐人毛文锡韵","f":"古风","c":["崧台暖，斜日海天低。","角弓齐。","雁行阵里，风轮丝上，危楼百尺听鸣鼙。","营帐北，女墙西。","报道右晴初注，惝恍意犹迷。","遥嘶影，碧草趁霜蹄。","靖蛮奚。","何须铁骑，一矢上云梯。"]},{"t":"凤衔杯 端溪任兵备席上，赠沉香杯","f":"古风","c":["秋水片帆明似箭。","又映带烟峦葱茜。","有垂钓任公，鸣筝挟瑟开芳宴。","还共举，梨花盏。","质崚嶒，气清远。","泛玻瓈、鹧鸪斑擅。","拚一饮香浮，醉中海国壶中选。","应胜似，涪阳篆。"]},{"t":"醉春风 其一 即事","f":"古风","c":["屈指三春尽。","重亿三秋信。","萧郎何事别经年，问。","问。","问。","欲语还停，一杯残酒，一天幽恨。","臂约黄金褪。","泪剪银缸晕。","萧娘对面隔天涯，近。","近。","近。","促坐藏钩，并肩倚笑，满怀风韵。"]},{"t":"醉春风 其二 有约","f":"古风","c":["帘外梨云冷。","帘内兰膏永。","碧阑干畔有人行，等。","等。","等。","绣幕风轻，纱窗月暗，芳心耿耿。","往事重思省。","未饮先酩酊。","悄闻侍女唤低声，请。","请。","请。","三载相思，办校良会，从今便肯。"]},{"t":"醉春风 其三 别况","f":"古风","c":["清影微含态。","红玉偏生黛。","侍儿浅覆夜深杯，怪。","怪。","怪。","五夜才分，三更欲别，一尊堂在。","醉里常相爱。","醒后谁相对。","风光瞥去剩销魂，再。","再。","再。","此夜离愁，今番况味，满船须载。"]},{"t":"风中柳 宿西溪精舍，和陈眉公韵","f":"古风","c":["天地蘧庐，檐底白云留宿。","绕清流、几间茅屋。","板桥几曲。","蒲帆几幅。","漾晴光，一帘新绿。","细笋丛生，删去短墙孙竹。","觅荒园、煮些溪簌。","青樽未足。","黄粱已熟。","享人间塞翁真福。"]},{"t":"麦秀两歧 罗岕焙茶","f":"古风","c":["罗岕旗枪别。","庙后奇芬绝。","趁晴天，齐采撷。","仙掌兰苕折。","携来轻篓枝和叶。","异香清冽。","细入筠盘列。","拍向斑笼爇。","火初红，泉新汲。","焙就春风隔。","制成玉乳光莹洁。","金茎消渴。"]},{"t":"酷相思 其一 两江代内","f":"古风","c":["帘卷帘垂朝复暮。","断送落红无数。","想杜鹃声里人何处。","春山也、留君住。","秋山也、留君住。","两峰三竺西泠渡。","旧是同行路。","总叮咛燕子浑无据。","春江也、随君去。","秋江也、随君去。"]},{"t":"酷相思 其二 亿旧","f":"古风","c":["小院深深帘影悄。","心字篆烟微袅。","听琵琶、欲拨相思调。","花前也、微微笑。","樽前也、微微笑。","到得而今分散了。","腊泪溶溶晓。","便梦中、有路浑难到。","春风也、侬知道。","春雨也、侬知道。"]},{"t":"芭蕉雨 雨中种芭蕉","f":"古风","c":["草帝擅名幽谷。","却移来种向、阑干曲。","过雨秋容新沐。","一任风里题笺，天边挂绿。","点点盈阶断续。","似恨潇湘独。","怯初寒怕著、蕉丝服。","闲徙倚、恁无聊，为谁捲尽芳心，千重似束。"]},{"t":"品令 罗岕苦雨寄内","f":"古风","c":["万里归来后。","恨离别、今还又。","自从分手，千行清泪，一天消瘦。","屈指端阳，最是伤心时候。","情怀非旧。","叹往事、休回首。","奈他几叠，青山遮断，玉人翠袖。","岕茗亲携，好待北窗晴昼。"]},{"t":"行香子 其一 湖滨即事","f":"古风","c":["青霭濛濛。","碧浪溶溶。","小桥环影漾晴空。","数间茅屋，一带层峰。","更几竿竹，几枝柳，几株松。","左呼欢伯，右抚孤桐。","吟成残句付奚童。","闲时泛棹，醉后支筇。","有杏花烟，桃花雨，楝花风。"]},{"t":"行香子 其二 村居","f":"古风","c":["水抱孤村。","篱掩闲门。","似柴桑隔断红尘。","岚光澹淡，草色缤纷。","恰花为友，石为丈，竹为君。","乌程酿酒，紫笋翻春，觉翛然鱼鸟相亲。","更邀野老，共与评论。","但一炉烟，一钩月，一帘云。"]},{"t":"玉梅令 曹溪折梅花有感","f":"古风","c":["玉人风韵。","洗铅华都尽。","曹溪滴水罗浮近。","看巡檐索笑，折取一枝枝，白雪轻携，红英微衬。","岭头香满，涧边月印。","偏隔断、江南春信。","只无根零落，更素影凄凉，争似我、天涯幽恨。"]},{"t":"声声令 风雨阻黄浦，忆弘载不得晤","f":"古风","c":["滔滔江涌，猎猎风狂。","暗吹疏雨打蓬窗。","盈盈一水，洒不住、泪千行。","看咫尺烟波混茫。","荒岸桃花，花外雾映红妆。","青藤低捲带垂杨。","孤帆飘泊，书半卷，酒盈觞。","还留得、远梦凄凉。"]},{"t":"锦缠道 泛太湖","f":"古风","c":["万顷琉璃，著我扁舟一叶。","溯流光、高歌击楫。","恍疑天上乘槎入。","破浪凭虚，稳泛鱼龙宅。","望苕霅烟迷，洞庭云黑。","任滔滔、五湖南北。","听榜人遥起渔歌指，风波处处，总付霜天笛。"]},{"t":"卖花声 春晚，和纪伯紫韵","f":"古风","c":["落尽樱桃，万点花飞一片。","绣窗闲、初停针线。","无情蜂蝶，争趁芳尘软。","下香阶，欲扶还倦。","游丝飞絮，好任东风吹转。","恨垂杨、空庭又晚。","遥山暮雨，泪染春江面。","倚妆楼，罗帷频捲。"]},{"t":"解佩令 咏柳","f":"古风","c":["波纹漾漾，春阴楚楚。","看青青、青垂树树。","暖暖寒寒，酝酿出、花花絮絮。","又难禁、风风雨雨。","棱棱腰瘦，纤纤眉妩，恨依依、飘飘如许。","点点飞飞，肠断绝、丝丝缕缕。","却无端、朝朝暮暮。"]},{"t":"青玉案 其一 蓉湖蟹","f":"古风","c":["芙蓉零落秋光断。","深巷初成曲簖。","郭索横行清水岸。","无肠应月，有心附火，芒稻输筐满。","文登十二原无算。","此处蝤蛑堪与伴。","斫雪含黄名独冠。","携来玉爪，持来左手，风味东篱畔。"]},{"t":"青玉案 其二 太湖虾","f":"古风","c":["湖波万顷明如练。","虾菜寻常堪贱。","水母空教无目见。","编诸绳缕，牵来笭网，早向冰盘荐。","为姑为妾应红遍。","偏此处沙虹色变。","玉鬣冰肌风格擅。","真堪佐酒，还宜下箸，好共霜橙片。"]},{"t":"青玉案 其三 戴家庙夜泊，和王仔园韵，戏示萧北江","f":"古风","c":["片帆日落孤云细。","野岸扁舟同系。","岱色云迷峰影翠。","断垣荒藓，古祠深树，极目烟波际。","沧州沽酒依稀记。","曾几日都成往事。","草屋斜扉灯火蔽。","青帘高捲，玉绳低度，难博村醪醉。"]},{"t":"感皇恩 感悟","f":"古风","c":["江海一微尘，长安棋局。","莫向槐安论荣辱。","轻肥跃马，四十三年何速。","黑甜馀半枕、黄粱熟。","安步当车，晚食当肉。","五柳七松并孤竹。","楞伽堆案，任彼辕驹局促。","萧然束缚去、荒山足。"]},{"t":"看花回 饮李太史维饶庭中赏桂","f":"古风","c":["司马家声旧谪仙。","才藻翩翩。","广寒宫里飘金粟，向小山新撤金莲。","无声清露冷，香满晴天。","独招隐士共婵娟。","绮席琼筵。","绿映雕盘黄映酒，殷勤刻烛抽笺。","自惭偃蹇客，烂醉花砖。"]},{"t":"凤凰阁 其一 闺忆","f":"古风","c":["记海棠开后，别郎时节。","郎归经岁无消息。","那更春城烽火，伤心行客。","揾珠泪、梦魂愁绝。","寄语平安，犹自离肠百结。","堪怜一纸千山隔。","地北天南，处处暮云萧瑟。","又不禁、杜鹃声咽。"]},{"t":"凤凰阁 其二 题孙无言半瓢居","f":"古风","c":["恰平分风月，半瓢孙子。","沧州半壁堆图史。","祗为求全，莫必得半而止。","算容膝、只应如此。","廉让之间，着我于中位置。","我生适志耳。","瓠落无成，剖尽茫茫底事。","君莫笑、一枝足矣。"]},{"t":"殢人娇 春雨","f":"古风","c":["无限春情，细雨丝丝如织。","带瞑连阴天做黑。","红尘紫陌，染就迷离色。","阑干外、困柳欺花无力。","此际佳人，泪痕同湿。","低飞燕子偏怜惜。","乍眠还醒，往事难重忆。","频怅望、芳草王孙消息。"]},{"t":"两同心 得内寄诗","f":"古风","c":["双鸿郑重，尺鲤殷勤。","乌丝展、寄来清泪，银钩划、蹄隐残痕。","还反覆，模糊小篆，依约螺纹。","读罢别离情绪，字字销魂。","黄姑恨、曲拈红豆，绿窗语、烛映青樽。","每记得，客函时启，粉墨常新。"]},{"t":"天仙子 其一 闺情，集唐诗","f":"古风","c":["二八三五闺心切。","行拾落花比容色。","却愁红粉泪痕生，长思忆。","何可得。","惟有风光与踪迹。","夜半酒醒凭槛立。","暗想仪形执刀尺。","谁怜梦好转相思，魂欲绝。","涕如雪。","凉月清辉满床席。"]},{"t":"天仙子 其二 闺怨，集唐词","f":"古风","c":["红蜡半销残焰短。","欹枕钗横云鬓乱。","好天良月尽伤心，纱窗暖。","金樽满。","何事狂夫音信断。","低语前欢频转面。","却怕良宵重梦见。","玉炉空袅寂寥香，珠帘捲。","芳草远。","旧恨年年秋不管。"]},{"t":"佳人醉 本事","f":"古风","c":["绣户轻绡低捲。","翠帐春情难遣。","正一樽引满。","四肢微入，玉慵香软。","倒镜红潮初晕，溜横波、粉腻桃花片。","鬓松钗亸。","娇倚郎扶，憨嫌婢见，笑影流苏颤。","春流浅。","频携茗碗。","好梦今宵未选。"]},{"t":"月上海棠 送别","f":"古风","c":["杜鹃声里垂杨暮。","恨匆匆、远送郎行处。","握手临岐，欲将双泪啼为雨。","留君住。","博得片时欢聚。","片时无计堪留住。","奈东风、反把郎吹去。","妾靠东风，今朝却被东风误。","落花飞絮。","都是相思路。"]},{"t":"江城子 江城寄内","f":"古风","c":["当时携手绿窗纱。","月初斜。","酒交加。","闲说离人，莫自到天涯。","真个天涯今更远，寻好梦，梦还赊。","万重烟水万重沙。","眺飞霞。","听归鸦。","节物惊心，两鬓点霜华。","折得春来消息至，凭驿使，语梅花。"]},{"t":"小桃红 咏小桃红菊花","f":"古风","c":["种擅秋花俊。","色比春花嫩。","拂拂丹葩，斑斑红雨，一天孤韵。","向徵君篱下问津来，错把桃源认。","气暖秋风困。","霜点春风晕。","带醉低开，和莺吹折，鬓边斜衬。","算高人晚节助幽人，销得佳人恨。"]},{"t":"连理枝 题蜀花宛酒之轩","f":"古风","c":["山色松鳞老。","树影泉声杪。","斑筠密致，湘帘低映，满轩风筱。","把东川西域总移来，听南窗高啸。","珠帐青阴晓。","锦石红巾绕。","离离马乳，声声杜宇，露垂烟袅。","醉凉州细认蜀宫时，齐怡情花鸟。"]},{"t":"千秋岁 其一 夏日湖村偶咏","f":"古风","c":["湖波开朗。","曲岸溪流响。","新畦润，松风漾。","短扉炎似火，老圃平于掌。","登场后，仓烟翠积黄云上。","斗斛夸丰穰。","姑妇争劳攘。","揎袖起，倾缸酿。","芦塘微月映，茅舍田歌唱。","更深后，提灯又欲叉鱼往。"]},{"t":"千秋岁 其二 夏日湖村偶咏","f":"古风","c":["沟塍新涨。","乐岁今年广。","三五伴，携车往。","桔槔欣蘸水，天汉齐飞浪。","平畴满，插匀千顷如针线。","雨过增微爽。","泥滑愁朝饷。","看馌妇，依依状。","加餐隔岁米，薄酒前宵酿。","临欲去，低回怕过欹桥上。"]},{"t":"离亭燕 旅燕","f":"古风","c":["拂水衔花一片。","恰睹双双轻燕。","问尔故巢何处是，似向主人依恋。","飞去又飞来，恐被秋风吹倦。","谁系红绡堪羡。","谁寄锦书如面。","冷落江南烟水候，曾到旧家庭院。","我自故乡遥梦，入关河愁断。"]},{"t":"西施 游西施山","f":"古风","c":["镜湖春水影溶溶。","一棹小桥通。","稽山回映处，石径碧玲珑。","为想苎萝村畔，才离却，恰向土城中。","浣纱当日原无伴，偏邀郑旦相同。","还堪笑、去笄填土孰为容。","刚得教成歌舞如花艳，送入馆娃宫。"]},{"t":"隔浦莲近拍 醉后入滆湖，和陆放翁韵","f":"古风","c":["扁舟远泛暮景。","薄醉凉飙醒。","似隔深深浦，幽香引入清境。","低锁云万顷。","芳蕖净。","渌水明于镜。","金波冷。","玉人凭槛，鸦翎乱挽犹整。","一船皓月，斜送满身花影。","斗转参横闲夜永。","风静。","梦回应到巫岭。"]},{"t":"师师令 席上赠晦仙","f":"古风","c":["烛光红透。","映玉人罗袖。","冰盘荐处拨银筝，听一缕、新词谱就。","莫惯娇嗔常阿母。","倩当筵消受。","停歌又把钩儿覆。","抵换纤纤手。","暗将星眼掷儿郎，钗影动、眉梢春漏。","底事因郎争饷酒。","郎莫杯空否。"]},{"t":"隔帘听 咏弹筝","f":"古风","c":["正是恹恹天气，十五盈盈女。","十三弦上情千缕。","看玉比蝉钿，银排雁柱。","弹再鼓。","动春纤、当窗手语。","音如诉。","含宫嚼羽。","婉转歌喉吐。","斜搊慢撚相思谱。","空闺似入，湘江凄楚。","潇潇雨。","偷将泪丝重数。"]},{"t":"风入松 归忆","f":"古风","c":["钗痕横月簟横秋。","香冷衾裯。","分明有个人欢笑，惊回首、烛影虚留。","更待续完残梦，起来寻忆难休。","一番滋味一番愁。","闲倚妆楼。","眼前便倩知心伴，才提起、欲诉无由。","愿得情如流水，流侬直向江州。"]},{"t":"传言玉女 雪夜，为邻女催妆","f":"古风","c":["春晕微红，消得绣帘微雪。","殷勤青女，绾同心双结。","吴盐轻撒，咏絮风情亲切。","纱笼对引，碎琼铺设。","说嫁心惊，镇日妆台痴绝。","娇嗔阿母，夫婿尤怜惜。","小捉养娘，私向窗前低说。","玉郎莫见，簸钱时节。"]},{"t":"何满子 娄江月夜，追忆先二兄文友","f":"古风","c":["天上依然皎皎，人间一别茫茫。","仿佛娄江曾共被，相携共倒壶觞。","转眼青樽红烛，回头宿草衰杨。","留得遗文千卷，空教泪落琴床。","想到孤坟今夜月，谁存复壁馀光。","夜雨机丝寡嫂，春风书馆儿郎。"]},{"t":"百媚娘 美人秋千","f":"古风","c":["梦入春愁难妥。","日漾清阴深锁。","红绳画板旗双飐，欲上翩然婀娜。","绣雀棱棱蝉翼亸。","掩映垂杨左。","燕剪晴波频堕。","鹘舞回风轻过。","云曳香绵摇綵柱，糁落一庭花朵。","促罢遗钗花下坐。","怯向花茵卧。"]},{"t":"解蹀躞 雨中过小孤山","f":"古风","c":["滚滚江流万折，突立波心上。","一峰崒嵂，任惊涛巨浪。","却怜神女生涯，变作小姑暮雨，遍将云酿。","堪想像。","谁谓无郎孤况。","有彭郎相傍。","盈盈一水，脉脉徒遥望。","那更晚色迷离，赢得无限凄凉，行人俯仰。"]},{"t":"剔银灯 咏灯花","f":"古风","c":["绣阁深沉人静。","仗一点兰膏凝。","滟滟玉缸，垂垂金蕊，似与枝头开竞。","芳心不定。","却笑把、灯花厮并。","昨夜妆台辉映。","空倚熏篝潜等。","牙蒜凄清，莲筹寂寞，耽误银屏漏水。","从今思省。","再不向、灯花侥幸。"]},{"t":"婆罗门引 赠竹夫人","f":"古风","c":["系传渭水，汉加凉郡职称尊。","青奴命好犹存。","不羡昭华秾李，潇洒出风尘。","却中空无物，热不因人。","冰雪为身。","此生骨节嶙峋。","总任翻云覆雨，婉转相亲。","秋风一起，君心欢爱已更新。","莫无端、便发娇嗔。"]},{"t":"荔枝香 吴道贤携赠蜜荔枝","f":"古风","c":["新岁松关高卧。","谁相过。","吾友满袖烟霞，携饷炎州果。","倾来白玉明肌，露滴瑶浆破。","奚必黛叶、湘枝绛囊裹。","想五月，星缀珠排如火。","凤爪龙牙，津液酸甜颗颗。","陈紫遗芳，色味经时隔江左。","好待熏风鼓柁。"]},{"t":"拍阑干 咏阑干","f":"古风","c":["回廊曲井。","垂杨摇漾空庭景。","十二帘低清昼永。","掩映朱文，斜覆湘文冷。","亚字玲珑梵字影。","折折周周，春恨重重省。","疏星淡月微风静。","只为多情，近水常相称。","玉人徙倚还频凭，几遍沉吟，敲断玉钗不应。"]},{"t":"于飞乐 其一 为梁大司农咏白鹦鹉","f":"古风","c":["正珠江，春晓也，使节遥临。","看画堂、银母屏深。","听雕栏，声乍啭，吉了清音。","怕施朱翠，只携来、白雪横襟。","想雪衣，名独擅，索影沉沉。","展黄冠、初晕檀心。","羽翩跹，冰檐畔，诗句高吟。","玉奴梦醒，伴梨花、和月相寻。"]},{"t":"于飞乐 其二 又咏红鹦鹉","f":"古风","c":["更奇毛，难自秘，时乐名闻。","记湘州、尚炳遗文。","体金精，含火德，羽翼缤纷。","秦宫入后，锁深笼、一片红云。","想玉壶，曾浴处，色染灵芸。","正翩翩、琥珀缨裙。","语分明，情婉转，报主恩勤。","春多忆侣，喜丹丘、赤凤为群。"]},{"t":"祝英台近 访祝英台故宅，用辛稼轩韵","f":"古风","c":["碧鲜庵，画溪渡。","目断鸳鸯浦。","庭院深深，尽日飞红雨。","望中鸟啄游丝，蝶粘飞絮。","仿佛与芳魂同住。","更愁觑。","禁得一树棠梨，暗把春光数。","生死情缘，听尽流莺语。","总教妆阁钟声，香奁佛火，长则任、精灵来去。"]},{"t":"扑蝴蝶 咏蝶","f":"古风","c":["紫燕黄鹂，凤子群相趁。","香国翩跹，自小生来韵。","韩凭绿径沾愁，宋玉红墙牵恨。","镇日桃花门巷。","轻狂尽。","漆园晓梦方酣，不管人春困。","罗巾扑后，怪粉残香褪。","拖时裙钗难分，飞上钗梁欲晕。","恐被多情错认。"]},{"t":"侧犯 杨秋屏舅偕饮芙蓉庵，用周清真韵","f":"古风","c":["茅庵负郭，一池渌水明妆靓。","波定。","恰玉女凌波映奁镜。","暗香飘曲槛，飞霭摇芳径。","风静。","娇欲语，亭亭弄妆影。","横塘雨过，微洒尘心莹。","应共省。","尽壶觞，录事严觥令。","良辰胜友，同归酩酊。","任他月落碧梧金井。"]},{"t":"四园竹 罗岕坐新竹下作","f":"古风","c":["筼筜幽谷，树树翠琅玕。","和烟滴露，负日凌云，清节巑岏。","旧梢长，新箨解、东风弄巧，一宵补尽残山。","忽惊看。","参差迸石穿篱，吹添碧玉千竿。","晚色斜侵书帙，响借鸣泉素影寒。","还试听，龙吟凤啸，空林月又团。"]},{"t":"御街行 其一 王仔园同年招饮小辋川，同吴天篆、潘原白、程穆倩","f":"古风","c":["辋川路转红桥下。","巷僻多车马。","牙签玉轴富装潢，堆绕一庭书画。","薜萝牵屋，烟花满砌，曲院真潇洒。","宜城细酿杯频把。","侍立都闲雅。","行厨雪片斫吴羹，银烛冰盘高驾。","分曹戏采，挥毫觅句，烂醉须今夜。"]},{"t":"御街行 其二 元夜踏灯词，和徐夫人燕京元夜韵","f":"古风","c":["百枝火树千金屧，宝马香尘不绝。","飞琼结伴试灯来，忍把檀郎轻别。","一回佯怒，一回微笑，小婢扶行怯。","石桥路滑缃钩蹑，向阿母低低说。","妲娥此夜悔还无？","怕入广寒宫阙。","不如归去，难忘畴昔，总是团圆月。"]},{"t":"一丛花 咏玫瑰花","f":"古风","c":["玉人晓起惜春残。","花事正阑珊。","卖花声送妆台畔，开篮处、艳紫浓殷。","万朵氤氲，一枝芬郁，和露撚来看。","檀郎昨向鬓边安。","镇日对红颜。","从今揉得花魂碎，细匀入、湘摺罗纨。","别样风流，馀香旖旎，犹拟傍云鬟。"]},{"t":"送我入门来 咏美人泪","f":"古风","c":["玉箸初垂，鲛珠初结，依稀非雾非霞。","一声河满，肠断雨如麻。","隔窗暗滴帘前竹，却唾袖、偏生石上花。","忆自萧郎去后，长向星前月下，拥髻嗟呀。","好倩飞鸿，缄寄与天涯。","秋波流共春波远，总万点封成一缕纱。"]},{"t":"过涧歇 其一 过三十九涧，逾襄王岭，入罗岕","f":"古风","c":["山叠叠，溪流曲曲。","大似雷轰，细似琮琤，碎玉声声续。","天际倒悬三峡，波漾千竿竹。","石齿冷，入手寒香沁新绿。","更耸身直上，鸟道清泉，羊肠翠麓。","扶杖云生足。","小憩松风，看摘春纤，轻携碧篓，村火几处茶初熟。"]},{"t":"过涧歇 其二 游七星岩","f":"古风","c":["山拔地，巍然平陆。","峭壁飞崖，北斗兀立，南澳灵光矗。","无数神工鬼斧，斫就玲珑屋。","烟霄迥，玉宇琼楼遍空谷。","拔萝穿窦入，箭筈斜通，波涛乱蹴。","紫翠怡心目。","蹑蹬抠衣，钟乳垂珠，苔花叠锦，一枕潺湲傍岩宿。"]},{"t":"过涧歇 其三 文殊台瀑布","f":"古风","c":["高台上，矗立孤塔。","下俯银河，直接飞流，三峡声闛鞳。","乱落万山深处，众响俱相答。","惊惝恍，黯黮蛟龙湿云合。","西峰偏突起，狮子崚嶒，怒涛低压。","耳畔风萧飒。","最上携筇，翠黛澄鲜，朱光煜爚，此景真得巨然法。"]},{"t":"镇西 踰黄芦岭，度金锁关","f":"古风","c":["汾阳西指，有插天垠崿。","亘石栈、冈峦纷错。","蹑芒屩。","看峰回径转，亥磴螺盘，羊肠路恶。","两崖去天如削。","列城郭。","倚崇墉绝顶，险同剑阁。","剩荒垣、断云残角。","谁疏凿。","自一夫荷戟，百万临关梭巡，前却河山，数重扃钥。"]},{"t":"金人捧露盘 骊山怀古","f":"古风","c":["遍骊山，云杳杳，路漫漫。","恨古今、成败无端。","周原烽火，还留祸水响潺湲。","西风落叶，惊回首、一炬烟寒。","几何时，英雄泪，枫叶染，晓霜丹。","总萧条、绣岭花残。","五陵无树，依然明月照秦关。","还试问，金钗玉笛，天上人间。"]},{"t":"红林檎近 咏佛手柑花","f":"古风","c":["南海春工早，西天秋意凉。","翠叶压霜橘，素葩发幽光。","散来雪山花瓣，淡扫佛国严妆。","清绝绮阁琼窗。","夜静梦魂香。","皓月澄疏影，冷蕊促飞觞。","匀膏渍粉，曾经共沐芬芳。","恰轻拈微笑，东风屈指，合掌云屏伴法王。"]},{"t":"踏青游 娄东清明","f":"古风","c":["北郭寻青，闲向百家坟畔。","总零落、秋千池馆。","新火累累新冢，荒草萋萋荒岸。","风送榆钱无算。","共阴风纸钱吹乱。","最是伤心，绣阁孤帷魂断。","恨春光、轻寒轻暖。","奈一别泉台，忍把流莺唤。","泪痕飞絮满。","暮雨潇潇愁伴。"]},{"t":"柳初新 本意，和丁飞涛韵","f":"古风","c":["柔条欲挽春光住。","嫩绿半含半吐。","捼蓝漱水，轻黄弄色，染就满溪花雾。","十五盈盈楚楚。","最销魂、章台初去。","多少莺歌燕语。","织春愁、万丝千缕。","愁眉乍展，纤腰学舞，怎禁得、欺烟困雨。","好向妆台共倚，任东风、一帘香絮。"]},{"t":"斗百花 腊月桃花","f":"古风","c":["晓放端溪棹稳。","似与武陵溪近。","波含腊月寒晖，树发艳阳春信。","开遍桃花，到处间柳遮梅，仿佛烟斜雾嫩。","细把侬芳认。","临水倚墙，紫陌红尘相映。","无言忽笑，小立东风微晕。","绣线初添，美人欲赚崔郎，拗上一枝云鬓。"]},{"t":"蓦山溪 宿栖云精舍","f":"古风","c":["参天黛色，染遍湖波绿。","无数乱峰横，辨三径、吾庐修竹。","开扉猿鸟，花雨过疏钟，清泉麓。","朱阑曲。","流水和云宿。","一瓶一钵。","白日消棋局。","香积腐儒餐，更随分、山肴野蔌。","六时寂寂，万壑变晴阴，张公谷。","君迁木。","梅老茶初熟。"]},{"t":"早梅芳 咏青梅","f":"古风","c":["玉肌清，冰魂瘦。","忽见浓阴覆。","深深庭院，一树垂垂伴晴昼。","枝头青子结，叶底繁英透。","试凌波微展，小摘纤纤手。","缀如珠，匀似豆。","曾撚妆台石。","晶盘初荐，较前酸楚应非旧。","盐和商相鼎，齿软吴姬口。","问东风、并蒂犹存否。"]},{"t":"新荷叶 夏景","f":"古风","c":["翠竹高梧，浓阴绿树婆娑。","昼永闲庭，燕雏莺友相过。","玉人此际，无情绪、初试轻罗。","微摇纨扇，好风蹙动湘波。","斜倚阑干，碧珠乱点池荷。","密簟疏帘，水纹一枕凉多。","素馨香满，新浴罢、重画双蛾。","流萤戏扑，坐看夜影明河。"]},{"t":"爪茉莉 客中秋病，和陈其年韵","f":"古风","c":["飒飒蛩鸣，萧萧叶响。","悲哉秋气，西来朝爽。","四时作客，恰三秋、心情微恙。","那更禁泪湿琵琶，江上数峰高唱。","乡关何处，万叠云山相向。","阅不尽惊涛骇浪。","此身原拟似浮萍，真凄怆。","只一七神楼，三杯浮蚁，便是元灵玉酱。"]},{"t":"拂霓裳 观兰语堂女乐","f":"古风","c":["蕙风天。","幽兰欲语气如烟。","帘幕静，画堂珍重启芳筵。","银丝镂雪鲙，玉茗泻冰泉。","月娟娟。","一行行、红粉拥神仙。","明珰翠袖，不羡锦瑟华年。","歌喉细，紫绡绛树斗妖妍。","檀槽催按拍，竹肉应鸣弦。","舞翩跹。","暗销魂、醉倚百花前。"]},{"t":"千秋岁引 寿许节母","f":"古风","c":["霞泛青鸾，风飘紫燕。","绛帐女宗人争羡。","熊丸素娴班氏管，轩车时剉陶家荐。","汝南龙，河东凤，皆邦彦。","有母兼将父道擅。","有儿贻厥孙谋善。","此日徽音满芳甸。","井阑秋结冰桃实，兰阶春荫神芝遍。","进金鹅，斟玉醴，瑶池宴。"]},{"t":"玉楼春 其一 闺情","f":"七言律诗","c":["晓临明镜肠堪绝。","天遣春风领春色。","才见开花又落花，可能相别还相忆。","锦帐罗帏羞更入。","银钥重关听未辟。","为君惆怅又黄昏，世间只有情难说。"]},{"t":"玉楼春 其二 闺情","f":"七言律诗","c":["金丝蹙雾红衫薄。","绝代佳人何寂寞。","鸟飞残照水烟开，霜覆鹤身松子落。","朝来始向花前觉。","瘦竹亸烟遮板阁。","但曾行处遍寻看，不然日暮还家错。"]},{"t":"玉楼春 其一 闺忆","f":"七言律诗","c":["越罗冷薄金泥重。","钿合碧寒龙脑冻。","绕径全低月树枝，峰影暗随云水动。","银筝夜久殷勤弄。","花落石亭添别梦。","一纸乡书泪滴穿，空廊鸟啄花砖缝。"]},{"t":"玉楼春 其二 闺忆","f":"七言律诗","c":["樱花永巷垂杨岸。","桃叶传情竹枝怨。","满庭芳草易黄昏，一去那知行近远。","宝匣尘昏蝉鬓乱。","斜插玉钗灯影畔。","锦囊封了又重开，千里梦随残月断。"]},{"t":"迷仙引 访迷楼故址","f":"古风","c":["棠梨香冷，御苑云深，迷楼何处。","堤畔销魂，只送行人来去。","摇荡春光如许。","似把兴亡诉。","看廿四桥头，三千殿脚，一天丝雨。","往事浑无据。","莫问离宫路。","蔓草寒烟，已耕断隋皇古墓。","纵昔日、明珰翠羽。","被东风添上，数抔黄土。"]},{"t":"满路花 其一 酬赠纪仲齐自汉阳之西江，即用原和周清真韵","f":"古风","c":["笔垂秋叶露，文涌梁园雪。","翩翩擅渤海、才华绝。","林宗潇洒，有角真堪折。","四海声名阔。","倾盖相逢，客中共数嘉节。","几声哀雁，叫得枫成血。","一片江天树、谁相接。","自携绿绮，曲调偏亲切。","都向琴心说。","鼓罢清风，拂拂飘来大别。"]},{"t":"满路花 其二 酬赠纪仲齐自汉阳之西江，即用原和周清真韵","f":"古风","c":["尽饮郎官酒，快榻龙丘雪。","紫马题黄鹤。","称双绝。","奕叶金貂，醉击珊瑚折。","天远孤帆阔。","放棹西江，历历晴川时节。","青衫湿泪，还洒榴花血。","春草池塘梦、烟波接。","逢迎处处，触景成悲切。","待向何人说。","且沽斗酒，莫赋骊驹欲别。"]},{"t":"洞仙歌 其一 张公洞","f":"古风","c":["童山寂历，有神仙窟宅。","鬼斧何年巨灵劈。","呀然开辟处、天壤中宽，深无极，直下鸿濛千尺。","炬光迷近远，线缕萦盘，侧厂飞梁度空碧。","出鸟道枝撑，迎面峥嵘，愁颠坠、低头踞蹐。","问丹灶、玉堂白云封，只怪石嵯峨，张公遗迹。"]},{"t":"洞仙歌 其二 善权洞","f":"古风","c":["嵚崎两洞，更善权深秀。","凿翠玲珑开户牖。","敞层霄、云气结就重楼，楼高下，风动悬崖激溜。","耸身穿诘屈，随下危梯，丝竹清音杂鼯鼬。","人世有仙田，白石充粮，兼环列、药炉茶臼。","但雷篆、犹存囤碑空，不禁得洞中，一时回首。"]},{"t":"洞仙歌 其三 夏日斋中苦热，和东坡夏夜韵","f":"古风","c":["小斋烦暑，团扇交挥汗。","一庭绿树炎氛满。","阑干畔、薰风触热吹来，炉香袅，几缕碧烟凌乱。","琅玕清枕簟，梦到羲皇，此中人不知有汉。","被蝉曳残声，唤醒桃源，茶初熟、桐阴斜转。","且奈向、月白露浓时，听白雪高歌，方空新换。"]},{"t":"秋夜月 蛟桥月夜","f":"古风","c":["长桥月夜。","拱南山，俯荆水，清辉平野。","一望白空城郭，翠浮松槚。","蟾镜启，彩虹落，烟波如画。","潇洒偏照，孝侯祠下。","尽如卿者。","蛟可屠，虎可射，人人虞夏。","剩得阴房鬼火，灵旗飘瓦。","蓼花飞，枫叶染，悲哉秋也。","秋光长则，向杯中泻。"]},{"t":"霜天晓角 长至夜同内拥炉煨芋作","f":"古风","c":["阴云低覆。","看绕檐冰溜。","一线初添时候，燃宫饼，销金兽。","罗襦翠袖。","促坐红炉右。","侍儿斜拨寒灰，煨紫芋，凭纤手。","殷勤夜久。","暖语欢情厚。","长愿一生同守，人如旧，愁还又。","横窗疏影，可似伊清瘦。","今宵好护瓶梅，把春光，先泄漏。"]},{"t":"蕙兰芳引 咏树兰","f":"古风","c":["西牖光风，正空谷、秋兰初发。","看九畹遗芳，一种幽姿堪别。","疏林细叶，映满树、垂垂香雪。","记携来岭海，人在瑶台冰阙。","种异珍珠，名传鱼子，数蕊千结。","怕众草为群，独自亭亭欲绝。","玉茎紫艳，共伊清冽。","爱多情、移傍枕函亲切。"]},{"t":"簇水 春雨","f":"古风","c":["密洒轻匀，东风几度廉纤雨。","空濛翠霭，一带迷离烟树。","做弄丝丝袅袅，铺遍芳郊路。","尽日里、欲飞还住。","惊春暮。","见陌上、归鞭急整，频怅望、增凄楚。","莺回燕掠，到处吹花沾絮。","更入巫山好梦，向晚萦情绪。","凭阑听、点点心头长贮。"]},{"t":"华胥引 题华胥杨妃春睡图","f":"古风","c":["玉精临砌，绮阁移春，夜明帘影。","雾鬓烟鬟，四肢红玉轻云映。","罗巾汗拭桃花，恰海棠厮并。","翠枕支痕，睡起横波微晕。","好梦谁惊，似忽被、渔阳唤醒。","钿合钗分，谁想花冠不整。","早是粉本流传，画图重省。","一幅生绡，消得银屏昼永。"]},{"t":"恩爱深 记得","f":"古风","c":["记得当初，曾私语酴醾下。","芳茵促坐，花枝低亚。","几曲柔肠，㕙毫吟就，香罗帕、细把侬欢写。","而今何事，暗愁萦惹。","卜尽金钱还是假。","只一幅蛮笺，消受半生良夜。","孤雁叫寒汀，凄凉絮出伤心话。","谁伴残灯影，听暮雨潇潇，泪珠同洒。"]},{"t":"江城梅花引 秋夜听内弹清江引","f":"古风","c":["半帘花影入房栊。","对孤桐。","抚丝桐。","鼓一再行，绕指动清风。","指下风生松下应，拂白石，响清泉，雨淙淙。","淙淙瑟瑟满晴空。","曲未终。","意无穷。","听也听也，听忽变、换羽移宫。","又似贯珠声断百寻中。","此夜香闺幽梦冷，月落也，飞别鹤，送归鸿。"]},{"t":"步月 月下携小婢登锡山","f":"古风","c":["八九峰峦，十三娇小，相携月下芳姿。","山空人静，玉臂倩扶持。","花弄影、浑身上下，风动竹、忽地惊疑。","偏消受，一天清景，冷露湿鞋儿。","望梁溪城郭，恰幽辉皎洁，处处追随。","扑流萤、微挥轻箑，倚翠袖、斜覆纤絺。","回船也，夫人犹自爱眠迟。"]},{"t":"惜红衣 午日桃溪舟中","f":"古风","c":["有水有山，无花无酒。","蒲根谁切，角黍空涎，雨湿征衫透。","蓬窗萧瑟，两三个、鹭朋鸥友。","怜否。","痛饮新茶，半醉歌铜斗。","海榴深院，綵线虚悬，此际频回首。","还忆去年时候，章江口。","随意钗符艾虎，异地银筝红袖。","总飘零，恰是，楚尾吴头如旧。"]},{"t":"八六子 其一 杨青岩舅遂初堂宴集","f":"古风","c":["遂初堂。","先生解组归来，引客壶觞。","正夭矫盆梅作供，玲珑绮石堪携，微风送凉。","流连带水回廊。","半壁青山图画，一帘白石羲皇。","更争拂吟笺，斜书绛帖，弹棋赌子，投壶角胜，总向竹叶徐倾家酝，紫茸频试新枪。","尽疏狂。","还教索醉千场。"]},{"t":"八六子 其二 游康山，同吴天篆、潘原白","f":"古风","c":["问康山。","重门窈窕深藏，曲巷回环。","正路转层台百折，堂开峰顶三楹，萧然掩关。","良朋缓步跻攀。","绕郭帆云樯影，隔江雾髻云鬟。","恰三月烟花，短垣纵目，万家楼阁，小亭徙倚，又见槛内名葩婀娜，枝头好鸟绵蛮。","客心闲。","解衣坐啸忘还。"]},{"t":"劝金船 舟上十八滩","f":"古风","c":["惊涛急溜淙淙响。","喷沫鱼龙漾。","大滩十八馀滩百，更惶恐难傍。","奇峰扑面，恰与船头相向。","船尾裂云穿石，如在天上。","长年贾勇声偏壮。","齐踏千层浪。","盘涡笑撇双兰桨。","似布帆风飏。","席帽轻衫，独倚舵楼凄爽。","忽忆那呵一曲，夜静犹唱。"]},{"t":"鱼游春水 潘园杜鹃","f":"古风","c":["积翠屏山曲。","遍河阳铜官金谷。","一声杜宇，惊起一枝踯躅。","愁绝春归花与鸟，江南望帝魂犹蜀。","泣露啼红，泪痕相续。","何事司花频促。","此地擅鹤林清福。","乱开殷紫猩红，照人心目。","丹楼叶绽榴房火，绛霄锦覆杯中醁。","影映幔亭，光摇银烛。"]},{"t":"雪狮儿 都门洗象词","f":"古风","c":["昼日阴阴，都门洗象，争传奇绝。","荡漾春波，士女六街填咽。","瑶光森列。","却低受、蛮奴羁绁。","鞭梢整、踏入金塘，素牙玉洁。","双帚缚来清刷。","正殷鼻成雷，怒蹄捲雪。","水面辚輑，倏忽山飞海决。","云兴电灭。","渐浴罢、含元仗立。","朝双阙。","拜舞御阶合节。"]},{"t":"愁春未醒 寄寿王闺媛玉映","f":"古风","c":["山阴钟秀，玉润冰清。","想吟红留箧，廿年坛坫女长城。","几首新诗，两字浮名误半生。","如今长愿，书开万卷，花祝千龄。","昔年楼上，满湖春水，依旧盈盈。","忽惊心、雨丝风絮，此恨曾经。","堆案楞伽，消尽徐娘老去情。","遥怜一样青衫，憔悴红粉飘零。"]},{"t":"一枝花 花下惊悟，用辛稼轩韵","f":"古风","c":["技学屠龙手。","智擅谈天口。","倚长空、下笔冲星斗。","想万里鞭箠，肯落他人后。","一旦灰心久。","总将相神仙，都听先生乌有。","风吹起、一池春皱。","独坐频搔首。","抚孤松、还是忘年友。","问蝼蚁乌鸢，也识王侯否。","寒食家家柳。","便到荒丘，谁消受、只鸡絮酒。"]},{"t":"鹊踏花翻 西秦车中携鹦鹉南归，数日飞去","f":"古风","c":["陇树秋深，秦宫月落，携将鹦鹉随归骑。","归来水驿山程，听慧堪论，新诗读向闺人记。","朱帘初捲忽开笼，青云直上堪垂翅。","惊视。","千里高飞难致。","空辜负、主人情意。","怎似燕燕相依，年年频至。","好把奇毛秘。","思乡莫便入函关，且教历尽江南地。"]},{"t":"宣清 秋闺月夜","f":"古风","c":["皎洁当秋夜，正金波乍挹，冰壶初濯。","看平铺鸳瓦琉璃，渐照到玉人绰约。","露冷霓裳，风清环佩，幽辉如握。","光欲滴，漏将阑，孤睡何曾便著。","恰似人间，青天碧海，反窃姮娥药。","奈楚簟凉多，越罗衾薄。","一点梦魂难托。","待不思量，问今宵、怎生拚却。"]},{"t":"意难忘 题神仙庵，赠高鍊师","f":"古风","c":["曲径云遮。","见绿阴深处，仿佛仙家。","小桥欹涧响，古屋带藤斜。","通碧落，锁烟霞。","翠竹映明沙。","人间世，葛翁遗井，试觅丹砂。","客来便煮胡麻。","更崖边泛酒，溪畔煎茶。","一声惊白鹤，三尺袖青蛇。","乘月驭，驾雷车。","采遍石坛花。","还记取、松枝手植，暗历年华。"]},{"t":"东风齐着力 客中元旦","f":"古风","c":["柏子扳春，松枝饯腊，又是新年。","韶华依旧，迢递滞云天。","记得故家庭院，欢令节、弟妹团圆。","椒盘荐，殷勤纤手，列坐长筵。","回首各风烟。","人不见、天涯椒景堪怜。","异乡朋好，促膝话缠绵。","处处闾阎揖让，空赢得、尺素名传。","无聊也，闲行坊曲，暗伫婵娟。"]},{"t":"辘轳金井 小鬟雨汲","f":"古风","c":["垂垂碧柳，拂朱门、雨滴银塘芳草。","鸦鬓初成，正临风娇小。","临流窈窕。","映秋水、远山眉绕。","雾縠烟鬟，湘滨洛浦，辘轳春晓。","瘦影亭亭自照。","尚怜卿未解，向卿微笑。","清浅波纹，怕玉钗轻掉。","罗裙半袅。","试汲取、冷泉多少。","皓腕频携，弓鞋半湿，丰姿偏好。"]},{"t":"法曲献仙音 其一 铜虎媒填词初成，听梁溪女郎为予歌二郎神一曲，喜而赋此","f":"古风","c":["钗闪银屏，帘垂碧月，填就新词铜虎。","黄绢深惭，朱唇轻啭，消得佳人含吐。","细味幽兰香气，偏识郎心苦。","郎无误。","有萧娘，殷勤堪顾。","红烛下、一字敲来宫谱。","拂拂堕梁尘，听袅袅、歌喉如缕。","笑问知音，闺阁外、可曾相许。","倩浮白、千杯领取，清商全部。"]},{"t":"法曲献仙音 其二 曹溪六祖袈裟","f":"古风","c":["织就木棉，裁成碧绢，光耀玉环金缕。","服号离尘，布名屈朐，一钵共来西土。","想夜半传心印，把心灯遮住。","宝林古。","历唐宋，禁闱崇护。","袈裟阔、都作河山坐。","具龙象，遍琳宫，怎犹存亚仙祠墓。","庾岭藏身，踞石根慧明辞去。","只密证潜符，千载信衣留处。"]},{"t":"满江红 其一 过金沙寺，为岳鄂王题壁处敬和原韵","f":"古风","c":["擐甲投戈，过萧寺、晨钟甫歇。","想当日、冲冠怒发，满怀忠烈。","剑气夜寒阳羡草，笔光阵扫金沙月。","拂残碑、遗恨对西湖，同悲切。","淮北耻，终难雪。","淮西议，终难灭。","叹黄龙未饮，金瓯还缺。","潭水秋吟名士句，冰天泪洒英雄血。","看阴阴、松柏向南枝，朝双阙。"]},{"t":"满江红 其二 拜岳鄂王墓，敬和原韵","f":"古风","c":["大树萧萧，对衰草、寒烟未歇。","凭吊处、孤忠涅背，伊周争烈。","石马昼嘶燕市雨，灵旗影断黄河月。","念当时、南渡只偏安，空关切。","三字狱，何时雪。","十年力，谁人灭。","为东窗一语，山河残缺。","银碗红啼娇女泪，玉环碧化苌弘血。","望冬青、尽处起西风，摇宫阙。"]},{"t":"满江红 其三 拜于忠肃公墓","f":"古风","c":["细雨斜烟，一抔土、松楸潇洒。","留万古、青山碧血，孤忠司马。","只手有权持国是，绕朝无力存宗社。","岂南还、才与复神州，台山下。","虎卧日，群谋罢。","龙飞日，群奸射。","置死生成败，无如公者。","事去北门弓鸟恨，功高西市啼鹃夜。","使英雄垂泪共栖霞，皆天也。"]},{"t":"满江红 其四 咏绿牡丹","f":"古风","c":["厌粉锈朱，十斛黛、春恩初沐。","写不出、苔痕蘸色，兰膏争馥。","却拟新螺宵挹露，浪猜幺凤朝迎旭。","宝如来、舌上现青莲，清波浴。","花瘦也，藏金屋。","花睡也，烧银烛。","信玉宜称碧，珠宜名绿。","青鬓学来梳未似，翠眉相对羞应簇。","便不须秾叶与扶持，风流足。"]},{"t":"满江红 其五 寿天闲伯","f":"古风","c":["高柳鸣蝉，平芜外、绿萝晴色。","要酌取、碧筒为寿，如松如柏。","黄绮衣冠留姓氏，浮丘笑傲耽泉石。","问白云、天上铸红颜，天闲客。","孤山耸，岚阴赤。","横河涨，溪光碧。","任飘飖紫府，摩挲铜狄。","花扑玉缸前岁酿，桃开瑶海今年宝。","正称觞、前席舞斑斓，芝兰室。"]},{"t":"满江红 其六 过周山人山居留宿","f":"古风","c":["咫尺扬帆，扁舟系、夫湫山麓。","闲对着、一湖春水，一湾新绿。","昨夜东风微雨过，涛声初涨溪桥曲。","抱众山、回合影参差，云为屋。","千年树，苍皮束。","十顷稻，黄精斸。","便呼儿揖客，举杯相属。","入馔自夸虾菜美，团炉尚想蹲鸱熟。","问山中、花信作春秋，无荣辱。"]},{"t":"满江红 其七 过周山人山居留宿","f":"古风","c":["且住为佳，趁孤踪、闲情野鹤。","堪爱是、青山绕屋，白云生阁。","种遍梨园张谷胜，相逢橘叟巴人乐。","但逍遥、一枕足邯郸，溪声觉。","千个竹，抽新箨。","千树果，辉双萼。","看残山剩水，放怀寥廓。","星历初占山鸟唤，国风细注山花落。","苦低头、惭愧野人非，微名缚。"]},{"t":"满江红 其八 怅怅词，和陈其年韵","f":"古风","c":["月白荒荒，那更是、乱云漠漠。","拔剑起、悲风吼地，青丘如削。","企脚琵琶天际想，伤神丝竹中年恶。","奈三春、长只为悲秋，惊瑶落。","房名药，陂名芍。","檐巢鹤，门罗雀。","任文魔山鬼，揶揄嗢噱。","横槊竟同垓下咏，唾壶也向炉头作。","有曹丘、还解重黄金，无人诺。"]},{"t":"满江红 其九 怅怅词，和陈其年韵","f":"古风","c":["穷达由天，拥万卷、百城南面。","都则是、子虚乌有，雄文谁荐。","长啸烟霞湖海伴，良辰樽俎逍遥撰。","尽诸君、钟鼎与山林，从吾便。","蛮与触，方酣战。","蜂与蚁，方开宴。","惜祖龙未竟，还留笔砚。","八九胸中云梦泽，三千书牍回心院。","醉中山、此日杖头钱，卿钗钏。"]},{"t":"满江红 其十 怅怅词，和陈其年韵","f":"古风","c":["泛宅浮家，卿笑谓、君其休矣。","算只有、五湖烟水，年年如此。","芳草遥天青欲白，晴波夕照金还紫。","载一天、风月满扁舟，玄真子。","山欲雨，嵩高玺。","花欲雨，湘东蕊。","恍清虚宾主，神霄奴婢。","被褐半疑火浣布，斟茶拟吸琼芝髓。","访灵威、七日学长生，饥仍死。"]},{"t":"满江红 其十一 怅怅词，和陈其年韵","f":"古风","c":["岸帻青山，长松下、谁修边幅。","痛饮酒、离骚半卷，不堪多读。","舌在徒成开口笑，途穷耻作雍门哭。","听凉州、歌罢又伊州，阳春曲。","数升玉，争如粟。","数竿竹，还须肉。","笑折腰五斗，何妨丛菊。","落落元龙披锦绣，纷纷巢许称臣仆。","又奚须、山水作清音，如琴筑。"]},{"t":"满江红 其十二 生日自寿","f":"古风","c":["皇揽揆余，正诞降、庚寅之日。","任数载、年来年去，年年如昔。","与世周旋吾作我，一家逆旅身为客。","尽浮生、转瞬付浮云，谁陈迹。","何处献，金门策。","何处访，谷城石。","只有花有酒，斯晨斯夕。","好泛五湖烟水舫，更消五岳平生屐。","踏齐州、九点暮烟还，如松柏。"]},{"t":"满江红 其一 寿史远公五十，用曹顾庵先生韵","f":"古风","c":["半百才名，指学海、词源杰出。","想廿载、分荣绛帐，广文清密。","内府流传羲献帖，国门争购丹青笔。","正新翻、艳曲付红牙，灵妃匹。","羡落纸，金壶漆。","羡起草，丹霞日。","看拂衣归里，满园榛栗。","海上安期瓜似枣，山中桃李人如木。","总消磨、一卷是楞伽，延年术。"]},{"t":"满江红 其二 倒和前韵","f":"古风","c":["周肉何妻，漫道是、长生仙术。","争似汝、长斋绣佛，丹炉服术。","少小自怜游猎赋，追陪空献雕陵栗。","更谁知、四十九年非，今何日。","容未老，髯如漆。","心未老，丝成匹。","恰悲来舞剑，兴酣摇笔。","千古图书身上下，一杯诗酒花疏密。","叹吾生、早已胜而翁，星星出。"]},{"t":"满江红 其三 与史远公谈往事，因忆范龙仙、沈康生诸公，二叠前韵","f":"古风","c":["臣罪当诛，曾负累、丝毫难出。","今已矣、文深胥吏，网罗尤密。","百万总由铢黍积，钱刀争胜如椽笔。","算书生、原不悔封侯，监门匹。","茂才举，胶投漆。","渭阳遇，云披日。","奈投臣有枣，报君无粟。","醉里尚寻玄石酒，相期便访刘商术。","问青天、公等致身时，将何术。"]},{"t":"满江红 其四 醉饮史远公斋中有感，四用回韵","f":"古风","c":["天地茫茫，愁无尽、销愁无术。","应只有、浇愁惟酒，不烦蔘术。","花下频招松下鹤，盘中又检山中栗。","料吾身、烂醉是生涯，须千日。","梦欲醒，庄周漆。","心常醉，刘伶匹。","任挥毫草檄，请缨投笔。","薄劣自甘糟粕劳，不才且入山林密。","抚长锥、终岁处囊中，何由出。"]},{"t":"满江红 其五 赠潘原白兼题新居，五叠前韵","f":"古风","c":["烂漫才华，惊人句、潘江涌出。","尽少年、狂歌作达，外疏中密。","红粉一生三妇艳，黄庭五色千枝笔。","更清泉、白石寓经纶，谁堪匹。","楹与桷，施丹漆。","亭与阁，凌云日。","恰满樽桑落，堆盘芋栗。","招隐小山俱是桂，高吟药圃宁须术。","人诸君、击剑复弹棋，纵横术。"]},{"t":"满江红 其六 寿潘原白三十，六用回韵","f":"古风","c":["冉冉流光，尽人世、谋身多术。","只如尔、神仙服食，胜餐芝术。","绛树横陈琳国李，青鸾争捧天台栗。","愿百年、七进九霞觞，从今日。","堪裕后，樊宏漆。","堪擅誉，徐卿匹。","看双双骥子，能文操笔。","怜我白头丘壑老，倚君紫禁经纶密。","好因时、莫便学蹉跎，乘风出。"]},{"t":"满江红 其七 赠张月陵，七叠前韵","f":"古风","c":["季方难兄，有爱弟、清河挺出。","群推是、池塘春草，玉和金密。","玩世文章科斗字，惊人风雨蛟龙笔。","记翩翩、裘马少年时，今无匹。","原不慕，对君漆。","谁能驻，援戈日。","恨间关转徙，艰难薪栗。","小艇载诗更载酒，砚田种秫非栽木。","听君家、说尽谷城书，还丹术。"]},{"t":"满江红 其八 送月陵入道，八用回韵","f":"古风","c":["散尽千金，学曼倩、善藏其术。","还更向、罗浮碧海，凤芝龙术。","槛外露滋金洞草，崖边云护仙舟栗。","采石坛、花满不知春，羲农日。","服上药，调浮漆。","星佩冷，虹霓匹。","只未忘绮语，更怀铅笔。","但令毛生名纸贵，不妨潘簟生尘密。","数床头、昨夜卖文钱，飘然出。"]},{"t":"满江红 其九 雪夜野泊，九叠前韵","f":"古风","c":["岁暮凄凉，系缆处、片帆初出。","蓬窗映、斜斜整整，似疏还密。","片影夜寒村点酒，六飞梦冷生花笔。","遍千山、何处一渔翁，孤舟匹。","灯宛宛，遥怜漆。","风猎猎，难回日。","觉布衾如水，手皴肌栗。","烛尽寒灰悲伏枕，炉存馀火思蒸术。","被饥驱、僵卧水之滨，贫无术。"]},{"t":"满江红 其十 与恽正叔相约同耕南田，十用回韵","f":"古风","c":["生不逢时，问谁是、锐情经术。","只吾尔、难医贫病，非关苓术。","田舍艳称十斛麦，封侯且等千株栗。","想人生、行乐是西畴，穰穰日。","琴上趣，何劳漆。","花间友，还相匹。","更较晴量雨，焚书掷笔。","二顷好供饘粥费，比邻不羡崇墉密。","但南山北与北山南，相携出。"]},{"t":"满江红 其一 登芜湖塔绝顶，用辛弃疾韵","f":"古风","c":["拾级而登，跨江表、曾霄突立。","凭槛望、烟帆沙鸟，连樯风急。","霞映楼船百仗火，云横铁锁千寻壁。","问何时、天堑限江南，谁曾识。","栏杆外，衣沾湿。","铃甋下，珠摇滴。","向苍苍搔首，遥遥空碧。","俯仰自悲身世事，奔驰空洒杨朱泣。","拟过江、也学贩缯人，同为客。"]},{"t":"满江红 其二 送韩珠崖太史奉诏归娶","f":"古风","c":["天上仙郎，却占尽、人间清福。","人都羡、门阑喜气，锦攒花簇。","威凤新膺博望选，求凤始叶和鸣卜。","正日边、遥捧五云还，芙蓉麓。","绾绶日，丹文毂。","合卺夕，金莲烛。","恰荣分紫诰，徽音堪续。","蕙圃门盈桃李树，鸾坡堂种蓝田玉。","拟明年、此际海珠生，华封祝。"]},{"t":"满江红 其三 忆故园种竹栽篱，怅然寄内","f":"古风","c":["何意卿卿，常则住、白鸥溪曲。","那更是、一春风雨，远山如沐。","插槿新栽空谷锦，移恨远带潇湘绿。","羡深闺、泉石费经营，翛然足。","还须种，柴桑菊。","原不慕，金门肉。","任花开花落，无荣无辱。","半阁遥临天似水，野航小泛人如玉。","倩天边、曾向故园飞，双黄鹄。"]},{"t":"满江红 其四 忆故园种竹栽篱，怅然寄内","f":"古风","c":["蓟北燕南，空自叹、风尘碌碌。","原无分、逍遥容与，一生清福。","樱笋江边春正好，莼鲈溪畔秋方熟。","只清风、明月不须钱，随时足。","柴门外，闲鸥鹜。","东轩内，栽松竹。","料归期未远，不容卿独。","皓腕共牵菱角美，冰盘满荐鸡头肉。","更隔年、预酿不时需，应千斛。"]},{"t":"满江红 其五 寿祖赞善勿庵，用梅村先生寿巢村相国韵","f":"古风","c":["绿鬓功名，雅自负、苍髯如戟。","恰又听、玉堂清漏，金门瑶瑟。","风动铃音趋直早，花移砖影挥毫毕。","共一春、携手上高楼，江南客。","文蔚起，名薰炙。","庭罗雀，尘凝席。","正承华初启，烽烟方息。","击楫谋成台上米，围棋齿折中门屐。","拟升平、朝野献南山，从今日。"]},{"t":"满江红 其六 寄怀祖赞善勿庵","f":"古风","c":["落托京华，凭坐卧、高楼百尺。","畅好是、玉河垂柳，凤城寒食。","苹果堆盘红半染，葡萄张幕青如滴。","黯销魂、还忆去年时，天涯隔。","谁啸咏，梁园雪。","空对酒，南窗月。","只归来风景，不堪重说。","拨刺刀鸣豉下鲙，穿泥笋迸篱边壁。","倩回风、迢递寄长安，云千叠。"]},{"t":"满江红 其一 同贺天山先生过篁川废园，和天山抒怀韵","f":"古风","c":["别业篁川，曾记得、昔年经此。","恰两岸、依依绿柳，树犹如是。","老屋欹斜仓鼠窜，丰碑倒折枯藤寄。","叹山川、无恙绮罗非，都休矣。","风潭上，泉还旨。","烟汀外，花还紫。","只空庭藻影，鱼鱼唯唯。","纵不长贫何足羡，便为老圃真堪耻。","继尚书、勋业等云霄，惟君耳。"]},{"t":"满江红 其二 同贺天山先生过篁川废园，和天山抒怀韵","f":"古风","c":["深柳堂成，难自掩、文章声价。","羡此日、绛纱高座，凌颜轹谢。","爝火百年供啸咏，龙鳞千仞凭潇洒。","想挥鞭、一蹙造青云，何难者。","且暂觅，玉山罅。","又何必，金门下。","任嵚崎历落，酒垆花社。","捉笔不须尊卫霍，读书久已轻曹马。","只此中、丘壑最移情，吾师也。"]},{"t":"满江红 其三 江行雨泊，再和前韵","f":"古风","c":["风雨江干，算旅况、谁能遣此。","几欲向、箜篌邻女，唤公无是。","一一江豚掀浪拜，双双哀雁沿洲寄。","看钓蓬、吹火夜灯红，归来矣。","新茗冽，醇醪旨。","片云黑，晚烟紫。","指楼船沧海，似闻阿唯。","展卷怕看梁宋事，持杯翻畏樽罍耻。","俯奔涛、千尺听江声，悲盈耳。"]},{"t":"满江红 其四 江行雨泊，再和前韵","f":"古风","c":["努力加餐，亟为问、江东米价。","堪叹息、空囊羞涩，长途衰谢。","万里帆随鸿影落，孤灯泪共牛衣洒。","抚龙泉、咄咄更书空，谁知者。","风淅淅，蓬窗罅。","波滚滚，樯乌下。","任江鱼吞槛，江欧迎社。","梦里绿阴蕉覆鹿，杯中清影程生马。","倚舵楼、准趁半江晴，来朝也。"]},{"t":"满江红 其五 望谢公青墩故园读书处，三和前韵","f":"古风","c":["北郭青墩，想魂魄、犹应恋此。","敢则谓、青山谢傅，将无同是。","相赏便携泉石意，自怡祗合烟霞寄。","正栖丘、饮谷十年前，难忘矣。","菱角美，香芹旨。","寒月白，暮云紫。","有晓猿夜鹤，招予唯唯。","纵隔千山还可共，不知一事徒深耻。","问半生、踪迹尚沉浮，无言耳。"]},{"t":"满江红 其六 望谢公青墩故园读书处，三和前韵","f":"古风","c":["瓦釜雷鸣，难复问、黄金土价。","阅多少、初莺早雁，花开叶谢。","炙毂因人谁见许，新亭有泪无从洒。","尽滔滔、日夜大江流，如斯者。","故园栗，微霜罅。","北堂枣，疏篱下。","爱鲍君知我，陈侯均社。","输粟昔曾传柱史，入赀犹欲夸司马。","遍天涯、购得计然书，何求也。"]},{"t":"满江红 其七 风雨泊舟江心，四和前韵","f":"古风","c":["亦复何为，奈范叔、一寒至此。","君不见、崩涛骇浪，滔滔皆是。","楚尾吴头家作寓，灯天砚地身为寄。","怅芦中、一叶两三人，真穷矣。","汲新水，逾甘旨。","被短褐，逾朱紫。","检齐梁旧史，掀髯曰唯。","天堑不矜衣带限，江流难刷降幡耻。","问六朝、遗恨几英雄，茫然耳。"]},{"t":"满江红 其八 风雨泊舟江心，四和前韵","f":"古风","c":["对此茫茫，何处问、垆边酒价。","那更禁、风吹浪打，水流花谢。","点点寒从双鬓入，丝丝愁共千行洒。","只此中、眼泪满春江，无穷者。","笑补石，虚空罅。","叹填海，蓬瀛下。","想隔江烟树，依稀村社。","带瞑连阴天似墨，湿云粘梦云如马。","总江南、江北影模糊，孤灯也。"]},{"t":"满江红 其一 谈沧孺属题挥锄居","f":"古风","c":["鸡犬云中，曾栖息、匡君岩腹。","问何事，入廛近市，诛茅结屋。","用拙也应长闭户，畏人原自成空谷。","绕疏篱、几曲最怡情，栽花竹。","波潋滟，千层縠。","烟葱茜，千章绿。","对湖山俯仰，赏心娱目。","瓜架斗棚晨复暮，带经负耒耕还读。","人纷争、收拾一蜗庐，消棋局。"]},{"t":"满江红 其二 过挥锄居，立和谈青雪韵","f":"古风","c":["环堵萧然，正潇洒、丰神自别。","荷锄倦、拥书万卷，不营三窟。","半亩笔耕东海粟，砚田卧采西山蕨。","对北窗、风物到羲皇，南楼月。","寻幽胜，头忘栉。","徒慷慨，心如结。","笑劳劳攘攘，长安车辙。","造父难追泛驾影，夸娥独许名缰撇。","拟此生、市隐杂鱼盐，藏身诀。"]},{"t":"满江红 其三 送潘原白令溆浦，用辛稼轩平湖南寇韵","f":"古风","c":["去矣安仁，惊憔悴、西风衣葛。","羡筮仕、桃花洞口，寻源而入。","江上月明乌鹊起，洞庭雾敛鱼龙泣。","却乘流、一叶望潇湘，波涛急。","莫草檄，临邛客。","非下濑，戈船力。","只鸣琴幕府，坐销锋镝。","吹笛自当兵十万，鼓刀恰向隆中出。","听楚歌、几曲静烽烟，谐金石。"]},{"t":"满江红 其四 送潘原白令溆浦，用辛稼轩平湖南寇韵","f":"古风","c":["坚壁罗洋，踞胜算、何须诸葛。","恰此日、义陵制锦，捷书飞入。","渺渺烟寒木叶下，滔滔溪冷潜蛟泣。","坐琴堂、高啸海天秋，沅流急。","渔父畔，沧浪客。","官中水，寥平力。","任健儿跃马，羌童鸣镝。","明月洞开青嶂合，罗公峰隐苍生出。","拥孤城、大小西山阳，藏书石。"]},{"t":"满江红 其五 蒜山晚眺，用梅村先生蒜山怀古韵","f":"古风","c":["拳石嵯峨，临断岸、丹崖百尺。","看一带、崩腾京口，惊涛飞入。","两岸分明南北堑，半江割据曹刘敌。","更年年、芳草阅齐梁，扁舟客。","烽火静，烟墩白。","钟鼓振，帆樯集。","俯镆铘峭崿，森陈戈戟。","铁瓮势连龙虎险，楼船日没鼋鼍宅。","听萧萧、丛竹响寒芦，吹横笛。"]},{"t":"满江红 其一 青墩夏咏，和陈其年江村韵","f":"古风","c":["别墅苍梧，矗云际、龙鳞千尺。","凭水阁、风漪销暑，疏帘看弈。","尘拭琉璃罗翠盖，藻翻笭箵跳银鲫。","尽北窗、高枕对书眠，床头易。","一室内，虚生白。","一庭外，苔成积。","看鹤雏离褷，凫儿飞拍。","半幅蔚蓝天似绮，数茎吟断须如戟。","听月明、寥亮不胜寒，南楼笛。"]},{"t":"满江红 其二 青墩夏咏，和陈其年江村韵","f":"古风","c":["鸂鶒，烟扉外、三三两两。","恰几曲、清流似镜，碧波如掌。","牛背牧童支笠去，陇头馌妇腰镰往。","喜登场、?稏遍黄云，人熙穰。","五亩宅，墙阴敞。","十顷地，秧针漾。","正平畴绿满，海榴红放。","蚯蚓歌长蛙鼓闹，桔槔声歇蝉吟响。","挈村农、社酒赛鸡豚，呼侬长。"]},{"t":"满江红 其三 青墩夏咏，和陈其年江村韵","f":"古风","c":["长日阴阴，隔阛阓、超然城市。","见一带、波蕖冉冉，汀蒲靡靡。","照箸冷淘槐叶脆，胶唇环饼松花美。","更烂蒸、香齑白鱼肥，冰厨里。","微吟倦，眠迟起。","独酌罢，炊菰米。","想田夫风味，年年如此。","闲课阿奴锄白术，忙催竖子寻苍耳。","只微躯、药物满园中，沾沾喜。"]},{"t":"满江红 其四 青墩夏咏，和陈其年江村韵","f":"古风","c":["一抹修眉，阴阴见、远峰罗立。","曾记得、扶筇洞岕，亲携茗汁。","轻篓藏芽和露撷，新泉带雨捎溪急。","捲湘纹、一缕飏茶烟，松风集。","蟹眼沸，花堪吸。","凤饼啜，香堪裛。","笑触炎褦襶，相逢车笠。","翠碗暗移蝉影动，绿鬟浅试春流涩。","待夜深、纤指进馀芳，横波湿。"]},{"t":"满江红 其五 青墩夏咏，和陈其年江村韵","f":"古风","c":["踯躅残红，听几处、催归鸭鵊。","隐隐见、平芜燕剪，落花波夹。","与我周旋从我好，用卿作达从卿法。","挽银河、万斛洗炎蒸，凉风霎。","髹几畔，添香鸭。","矮屋畔，闲畚锸。","到采菱剥芡，不忧贫乏。","虎刺结成颗颗豆，凤仙染就纤纤甲。","折一枝、斜插鬓云边，银钗压。"]},{"t":"满江红 其六 青墩夏咏，和陈其年江村韵","f":"古风","c":["积翠攒青，偏杰出、小山乔木。","清影下、婆娑午梦，黄粱新熟。","花酿蜡房蜂炼蜜，雪堆竹箔蚕登簇。","羡满林、无数蜕龙孙，千竿竹。","窥影鹭，翘溪足。","噪檐鹊，巢丛绿。","听鸟啼未已，蛩吟方续。","钓槛收缗斜柳骨，微光趁月摊书读。","涨一篙、绿水泛轻航，波纹縠。"]},{"t":"满江红 其七 青墩夏咏，和陈其年江村韵","f":"古风","c":["小阁如船，恰新构、青墩之石。","还栽就、樱桃百树，蕉桐半亩。","嫩箨雨移旁舍竹，纤腰露染垂堤柳。","倚西风、落笔啸高天，惊南斗。","捞虾妾，捕鱼舅。","我欲醉，谋诸妇。","好开樽便饮，瓮馀残酒。","半卷离骚消白眼，一房莲子凭纤手。","仰林梢、唤起月当头，成三友。"]},{"t":"满江红 其八 青墩夏咏，和陈其年江村韵","f":"古风","c":["百顷风潭，镇一派、空明浩渺。","遥掩映、捼蓝漱碧，丛芦幽筱。","瓜嚼水精白袷冷，李沉玉甃红尘少。","送馀凉、几阵藕丝风，荷香绕。","溪瑟瑟，窗纱窅。","波滟滟，新蟾皎。","恰瓯斟绿醑，觞浮清醥。","销帐四垂冰簟展，琼奁半启帘漪悄。","理瑶琴、一曲落平沙，飞鸿矫。"]},{"t":"满江红 其九 青墩夏咏，和陈其年江村韵","f":"古风","c":["万绿丛深，忽点缀、黄鹂两个。","日趖午、槐阴斜转，苔阴低簸。","赤苋紫茄田野味，芋区瓜架园蔬课。","问白头、遗老话桃源，随风唾。","长松下，结趺坐。","疏藤上，曲肱卧。","喜日长无事，壶中天大。","待月且乘烟水舫，凌云欲鼓潇湘舵。","傍柴门、犬吠竹边桥，谁相过。"]},{"t":"满江红 其十 青墩夏咏，和陈其年江村韵","f":"古风","c":["铁笛凄清，三弄后、高云欲裂。","还消受、篆烟几缕，匡床八尺。","浴罢芙蕖花底湿，妆残茉莉香中觅。","对团圞、素月坐长风，松间石。","纨扇扑，萤飞急。","金井断，虫吟逼。","叹中年以后，伤神何益。","夜永试寻河朔饮，数奇莫去蓝田射。","玉绳低、急雨响琮琤，冰弦砉。"]}]};